{
  "name": "Page Q&A Extractor",
  "description": "Snap a picture of any page and this app will use AI to generate a list of questions and answers from its content. You can even listen to the answers read aloud.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useCallback, useRef } from 'react';
import { QA_Pair } from './types';
import { generateQuestionsFromImage } from './services/geminiService';
import QuestionAccordion from './components/QuestionAccordion';
import { CameraIcon, SparklesIcon, XCircleIcon, ArrowUpOnSquareIcon } from './components/icons';

type LoadingState = 'idle' | 'processing' | 'success' | 'error';

const App: React.FC = () => {
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [qaPairs, setQaPairs] = useState<QA_Pair[]>([]);
  const [loadingState, setLoadingState] = useState<LoadingState>('idle');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      processFile(file);
    }
  };

  const processFile = (file: File) => {
    setImageFile(file);
    const reader = new FileReader();
    reader.onload = (e) => {
      setImageUrl(e.target?.result as string);
      setQaPairs([]);
      setLoadingState('idle');
      setErrorMessage(null);
    };
    reader.readAsDataURL(file);
  };

  const handleDrop = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.remove('border-indigo-500');
    const file = event.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) {
        processFile(file);
    }
  };

  const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
  };

  const handleDragEnter = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.add('border-indigo-500');
  };

  const handleDragLeave = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.remove('border-indigo-500');
  };

  const handleSubmit = useCallback(async () => {
    if (!imageUrl) return;

    setLoadingState('processing');
    setErrorMessage(null);
    setQaPairs([]);

    try {
      // The base64 URL is in the format "data:image/jpeg;base64,..."
      // We need to extract just the base64 part.
      const base64Data = imageUrl.split(',')[1];
      const result = await generateQuestionsFromImage(base64Data, imageFile?.type || 'image/jpeg');
      setQaPairs(result);
      setLoadingState('success');
    } catch (error) {
      console.error(error);
      setErrorMessage(error instanceof Error ? error.message : 'An unknown error occurred.');
      setLoadingState('error');
    }
  }, [imageUrl, imageFile]);

  const handleReset = () => {
    setImageFile(null);
    setImageUrl(null);
    setQaPairs([]);
    setLoadingState('idle');
    setErrorMessage(null);
    if(fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 flex flex-col items-center p-4 sm:p-6 lg:p-8">
      <div className="w-full max-w-4xl mx-auto">
        <header className="text-center mb-8">
          <h1 className="text-4xl sm:text-5xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-indigo-600">
            Page Q&A Extractor
          </h1>
          <p className="mt-2 text-lg text-gray-400">
            Upload a picture of a page, and let AI generate questions and answers from it.
          </p>
        </header>

        <main className="bg-gray-800 rounded-2xl shadow-2xl p-6">
          {!imageUrl ? (
            <div 
              className="w-full h-64 border-4 border-dashed border-gray-600 rounded-xl flex flex-col justify-center items-center text-center cursor-pointer hover:border-indigo-500 transition-colors duration-300"
              onClick={() => fileInputRef.current?.click()}
              onDrop={handleDrop}
              onDragOver={handleDragOver}
              onDragEnter={handleDragEnter}
              onDragLeave={handleDragLeave}
            >
              <CameraIcon className="w-16 h-16 text-gray-500 mb-4" />
              <h2 className="text-xl font-semibold text-gray-300">Upload an Image</h2>
              <p className="text-gray-400">Click to browse or drag & drop an image here</p>
              <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileChange}
                accept="image/*"
                className="hidden"
              />
            </div>
          ) : (
            <div className="flex flex-col lg:flex-row gap-6">
              <div className="lg:w-1/2 flex-shrink-0">
                <div className="relative group">
                  <img src={imageUrl} alt="Uploaded page" className="w-full h-auto object-contain rounded-lg shadow-lg max-h-[60vh]" />
                  <button onClick={handleReset} className="absolute top-2 right-2 p-2 bg-black bg-opacity-50 rounded-full text-white hover:bg-opacity-75 transition-all opacity-0 group-hover:opacity-100 focus:opacity-100">
                    <XCircleIcon className="w-6 h-6" />
                  </button>
                </div>
                {loadingState !== 'processing' && (
                  <button
                    onClick={handleSubmit}
                    disabled={loadingState === 'processing'}
                    className="mt-4 w-full bg-indigo-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-colors duration-300 disabled:bg-gray-500 disabled:cursor-not-allowed"
                  >
                    <SparklesIcon className="w-6 h-6" />
                    Generate Q&A
                  </button>
                )}
              </div>
              <div className="lg:w-1/2 flex flex-col">
                {loadingState === 'processing' && (
                  <div className="flex flex-col items-center justify-center h-full text-center">
                    <div className="w-12 h-12 border-4 border-t-indigo-500 border-gray-600 rounded-full animate-spin mb-4"></div>
                    <p className="text-lg font-semibold text-gray-300">Analyzing your document...</p>
                    <p className="text-gray-400">This might take a moment.</p>
                  </div>
                )}
                {loadingState === 'error' && (
                  <div className="flex items-center justify-center h-full text-center bg-red-900 bg-opacity-30 p-4 rounded-lg">
                    <div>
                      <XCircleIcon className="w-12 h-12 text-red-400 mx-auto mb-2" />
                      <p className="text-red-400 font-semibold">An error occurred</p>
                      <p className="text-red-300 text-sm">{errorMessage}</p>
                    </div>
                  </div>
                )}
                {loadingState === 'success' && qaPairs.length > 0 && (
                  <div className="space-y-3 overflow-y-auto max-h-[70vh] pr-2">
                    <h3 className="text-2xl font-bold mb-4 text-gray-200">Generated Questions</h3>
                    {qaPairs.map((pair, index) => (
                      <QuestionAccordion key={index} qaPair={pair} />
                    ))}
                  </div>
                )}
                 {loadingState === 'success' && qaPairs.length === 0 && (
                  <div className="flex items-center justify-center h-full text-center bg-gray-700 bg-opacity-50 p-4 rounded-lg">
                    <div>
                      <p className="text-lg font-semibold text-gray-300">No questions found</p>
                      <p className="text-gray-400">The AI couldn't extract any Q&A from the image. Please try a different one.</p>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

export interface QA_Pair {
  question: string;
  answer: string;
}

import React, { useState, useRef } from 'react';
import { QA_Pair } from '../types';
import { generateSpeech } from '../services/geminiService';
import { decode, decodeAudioData } from '../utils/audioUtils';
import { ChevronDownIcon, SpeakerWaveIcon, SpeakerXMarkIcon } from './icons';

interface QuestionAccordionProps {
  qaPair: QA_Pair;
}

const QuestionAccordion: React.FC<QuestionAccordionProps> = ({ qaPair }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<AudioBufferSourceNode | null>(null);

  const handlePlayAudio = async (text: string) => {
    if (isPlaying && sourceRef.current) {
        sourceRef.current.stop();
        setIsPlaying(false);
        return;
    }

    setIsGenerating(true);
    try {
        const audioBase64 = await generateSpeech(text);

        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const audioContext = audioContextRef.current;
        if(audioContext.state === 'suspended') {
          await audioContext.resume();
        }

        const audioBuffer = await decodeAudioData(decode(audioBase64), audioContext, 24000, 1);

        const source = audioContext.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(audioContext.destination);
        source.onended = () => {
            setIsPlaying(false);
            sourceRef.current = null;
        };
        source.start();
        sourceRef.current = source;
        setIsPlaying(true);
    } catch (error) {
        console.error("Failed to play audio:", error);
    } finally {
        setIsGenerating(false);
    }
  };

  return (
    <details className="group bg-gray-700 rounded-lg overflow-hidden transition-all duration-300">
      <summary className="p-4 flex justify-between items-center cursor-pointer list-none hover:bg-gray-600">
        <span className="font-semibold text-gray-200">{qaPair.question}</span>
        <ChevronDownIcon className="w-5 h-5 text-gray-400 transition-transform duration-300 group-open:rotate-180" />
      </summary>
      <div className="p-4 border-t border-gray-600 bg-gray-800">
        <p className="text-gray-300 whitespace-pre-wrap">{qaPair.answer}</p>
        <div className="mt-4">
          <button
            onClick={() => handlePlayAudio(qaPair.answer)}
            disabled={isGenerating}
            className="flex items-center gap-2 text-sm text-indigo-400 hover:text-indigo-300 disabled:text-gray-500 disabled:cursor-wait"
            aria-label={isPlaying ? 'Stop reading answer' : 'Read answer aloud'}
          >
            {isGenerating ? (
              <>
                <div className="w-4 h-4 border-2 border-t-indigo-400 border-gray-600 rounded-full animate-spin"></div>
                Generating...
              </>
            ) : isPlaying ? (
              <>
                <SpeakerXMarkIcon className="w-5 h-5" />
                Stop
              </>
            ) : (
              <>
                <SpeakerWaveIcon className="w-5 h-5" />
                Read Aloud
              </>
            )}
          </button>
        </div>
      </div>
    </details>
  );
};

export default QuestionAccordion;

