import { GoogleGenAI, Type, Modality } from "@google/genai";
import { QA_Pair } from '../types';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable is not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const qaSchema = {
    type: Type.ARRAY,
    items: {
        type: Type.OBJECT,
        properties: {
            question: {
                type: Type.STRING,
                description: "A question generated from the text."
            },
            answer: {
                type: Type.STRING,
                description: "The answer to the generated question, found in the text."
            },
        },
        required: ["question", "answer"],
    },
};

export async function generateQuestionsFromImage(base64ImageData: string, mimeType: string): Promise<QA_Pair[]> {
    const imagePart = {
        inlineData: {
            data: base64ImageData,
            mimeType: mimeType,
        },
    };

    const textPart = {
        text: "Analyze the content of this image. Generate a comprehensive list of questions and their corresponding answers based *only* on the text visible in the image. Format the output as a JSON array of objects, where each object has a 'question' and an 'answer' key.",
    };

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            // FIX: Reordered parts to place image before text prompt, aligning with best practices.
            contents: { parts: [imagePart, textPart] },
            config: {
                responseMimeType: "application/json",
                responseSchema: qaSchema,
            },
        });

        const jsonText = response.text;
        if (!jsonText) {
            throw new Error("API returned an empty response.");
        }

        const parsedJson = JSON.parse(jsonText);
        return parsedJson as QA_Pair[];

    } catch (error) {
        console.error("Error calling Gemini API:", error);
        throw new Error("Failed to generate questions from the image. Please check the console for details.");
    }
}


export async function generateSpeech(text: string): Promise<string> {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' },
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

        if (!base64Audio) {
            throw new Error("No audio data returned from the API.");
        }

        return base64Audio;
    } catch (error) {
        console.error("Error generating speech:", error);
        throw new Error("Failed to generate speech. Please check the console for details.");
    }
}

import React, { useState, useRef } from 'react';
import { QA_Pair } from '../types';
import { generateSpeech } from '../services/geminiService';
import { decode, decodeAudioData } from '../utils/audioUtils';
import { ChevronDownIcon, SpeakerWaveIcon, SpeakerXMarkIcon, XCircleIcon } from './icons';

interface QuestionAccordionProps {
  qaPair: QA_Pair;
}

const QuestionAccordion: React.FC<QuestionAccordionProps> = ({ qaPair }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [audioError, setAudioError] = useState<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<AudioBufferSourceNode | null>(null);

  const handlePlayAudio = async (text: string) => {
    setAudioError(null); // Clear previous errors on a new attempt

    if (isPlaying && sourceRef.current) {
        sourceRef.current.stop();
        setIsPlaying(false);
        return;
    }

    setIsGenerating(true);
    try {
        const audioBase64 = await generateSpeech(text);

        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const audioContext = audioContextRef.current;
        if(audioContext.state === 'suspended') {
          await audioContext.resume();
        }

        const audioBuffer = await decodeAudioData(decode(audioBase64), audioContext, 24000, 1);

        const source = audioContext.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(audioContext.destination);
        source.onended = () => {
            setIsPlaying(false);
            sourceRef.current = null;
        };
        source.start();
        sourceRef.current = source;
        setIsPlaying(true);
    } catch (error) {
        console.error("Failed to play audio:", error);
        setAudioError("Could not generate audio due to high demand. Please try again later.");
        // Clear the error message after 5 seconds
        setTimeout(() => setAudioError(null), 5000);
    } finally {
        setIsGenerating(false);
    }
  };

  return (
    <details className="group bg-gray-700 rounded-lg overflow-hidden transition-all duration-300">
      <summary className="p-4 flex justify-between items-center cursor-pointer list-none hover:bg-gray-600">
        <span className="font-semibold text-gray-200">{qaPair.question}</span>
        <ChevronDownIcon className="w-5 h-5 text-gray-400 transition-transform duration-300 group-open:rotate-180" />
      </summary>
      <div className="p-4 border-t border-gray-600 bg-gray-800">
        <p className="text-gray-300 whitespace-pre-wrap">{qaPair.answer}</p>
        <div className="mt-4">
          <button
            onClick={() => handlePlayAudio(qaPair.answer)}
            disabled={isGenerating}
            className="flex items-center gap-2 text-sm text-indigo-400 hover:text-indigo-300 disabled:text-gray-500 disabled:cursor-wait"
            aria-label={isPlaying ? 'Stop reading answer' : 'Read answer aloud'}
          >
            {isGenerating ? (
              <>
                <div className="w-4 h-4 border-2 border-t-indigo-400 border-gray-600 rounded-full animate-spin"></div>
                Generating...
              </>
            ) : isPlaying ? (
              <>
                <SpeakerXMarkIcon className="w-5 h-5" />
                Stop
              </>
            ) : (
              <>
                <SpeakerWaveIcon className="w-5 h-5" />
                Read Aloud
              </>
            )}
          </button>
          {audioError && (
            <p className="mt-2 text-sm text-red-400 flex items-center gap-2">
              <XCircleIcon className="w-5 h-5" />
              <span>{audioError}</span>
            </p>
          )}
        </div>
      </div>
    </details>
  );
};

export default QuestionAccordion;

