                        <div className="space-y-3">
                          {educationalContent.formulaExplanations.map((item, index) => (
                            <div key={index} className="bg-gray-700 p-4 rounded-lg">
                                <p className="font-mono text-indigo-300 text-lg mb-2">{item.formula}</p>
                                <p className="text-gray-300 whitespace-pre-wrap">{item.explanation}</p>
                            </div>
                          ))}
                        </div>
                      </section>
                    )}

                    <section>
                      <h3 className="text-2xl font-bold mb-3 text-gray-200">📝 Short Answer Questions</h3>
                      <div className="space-y-3">
                        {educationalContent.shortAnswerQuestions.map((pair, index) => (
                          <QuestionAccordion key={`short-${index}`} qaPair={pair} />
                        ))}
                      </div>
                    </section>

                    <section>
                      <h3 className="text-2xl font-bold mb-3 text-gray-200">📖 Long Answer Questions</h3>
                      <div className="space-y-3">
                        {educationalContent.longAnswerQuestions.map((pair, index) => (
                          <QuestionAccordion key={`long-${index}`} qaPair={pair} />
                        ))}
                      </div>
                    </section>

                    <section>
                      <h3 className="text-2xl font-bold mb-3 text-gray-200">🧠 Multiple Choice Questions</h3>
                      <div className="space-y-3">
                        {educationalContent.multipleChoiceQuestions.map((mcq, index) => (
                          <MCQItem key={`mcq-${index}`} mcq={mcq} />
                        ))}
                      </div>
                    </section>
                  </div>
                )}
                 {loadingState === 'success' && !educationalContent && (
                  <div className="flex items-center justify-center h-full text-center bg-gray-700 bg-opacity-50 p-4 rounded-lg">
                    <div>
                      <p className="text-lg font-semibold text-gray-300">No content found</p>
                      <p className="text-gray-400">The AI couldn't create a study guide from the image. Please try a different one.</p>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

export interface QA_Pair {
  question: string;
  answer: string;
}

export interface MCQ {
  question: string;
  options: string[];
  correctAnswer: string;
}

export interface FormulaExplanation {
    formula: string;
    explanation: string;
}

export interface EducationalContent {
  topicSummary: string;
  shortAnswerQuestions: QA_Pair[];
  longAnswerQuestions: QA_Pair[];
  multipleChoiceQuestions: MCQ[];
  formulaExplanations: FormulaExplanation[];
}

import React, { useState } from 'react';
import { MCQ } from '../types';
import { CheckCircleIcon, LightBulbIcon } from './icons';

interface MCQItemProps {
  mcq: MCQ;
}

const MCQItem: React.FC<MCQItemProps> = ({ mcq }) => {
  const [showAnswer, setShowAnswer] = useState(false);
  const optionLabels = ['A', 'B', 'C', 'D'];

  return (
    <div className="bg-gray-700 rounded-lg p-4 transition-all duration-300">
      <p className="font-semibold text-gray-200 mb-3">{mcq.question}</p>
      <div className="space-y-2">
        {mcq.options.map((option, index) => {
          const isCorrect = option === mcq.correctAnswer;
          let optionClass = "flex items-center gap-3 p-2 rounded-md transition-colors duration-200";
          if (showAnswer) {
            optionClass += isCorrect ? " bg-green-500/20 text-green-300" : " text-gray-400";
          } else {
            optionClass += " hover:bg-gray-600";
          }
          return (
            <div key={index} className={optionClass}>
              <span className={`font-bold ${showAnswer && isCorrect ? 'text-green-300' : 'text-gray-400'}`}>{optionLabels[index]})</span>
              <span>{option}</span>
              {showAnswer && isCorrect && <CheckCircleIcon className="w-5 h-5 ml-auto text-green-400" />}
            </div>
          );
        })}
      </div>
      {!showAnswer && (
        <div className="mt-4 text-right">
          <button
            onClick={() => setShowAnswer(true)}
            className="flex items-center gap-2 text-sm text-indigo-400 hover:text-indigo-300 ml-auto"
          >
            <LightBulbIcon className="w-5 h-5" />
            Show Answer
          </button>
        </div>
      )}
    </div>
  );
};

export default MCQItem;

