import React, { useState, useEffect, useCallback } from 'react';
import { MCQ } from '../types';
import { ClockIcon } from './icons';

interface QuizViewProps {
  mcqs: MCQ[];
  onQuizComplete: (answers: (string | null)[]) => void;
}

const QUIZ_DURATION_SECONDS = 180; // 3 minutes

const QuizView: React.FC<QuizViewProps> = ({ mcqs, onQuizComplete }) => {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<(string | null)[]>(() => Array(mcqs.length).fill(null));
  const [timeLeft, setTimeLeft] = useState(QUIZ_DURATION_SECONDS);

  const handleFinishQuiz = useCallback(() => {
    onQuizComplete(selectedAnswers);
  }, [onQuizComplete, selectedAnswers]);

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLeft(prevTime => {
        if (prevTime <= 1) {
          clearInterval(timer);
          handleFinishQuiz();
          return 0;
        }
        return prevTime - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [handleFinishQuiz]);

  const handleSelectAnswer = (option: string) => {
    const newAnswers = [...selectedAnswers];
    newAnswers[currentQuestionIndex] = option;
    setSelectedAnswers(newAnswers);
  };

  const handleNext = () => {
    if (currentQuestionIndex < mcqs.length - 1) {
      setCurrentQuestionIndex(prev => prev + 1);
    }
  };

  const handlePrev = () => {
    if (currentQuestionIndex > 0) {
      setCurrentQuestionIndex(prev => prev - 1);
    }
  };

  const currentQuestion = mcqs[currentQuestionIndex];
  const minutes = Math.floor(timeLeft / 60);
  const seconds = timeLeft % 60;

  return (
    <div className="bg-gray-700 p-6 rounded-lg shadow-lg animate-fade-in">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl font-bold text-indigo-300">Timed Quiz</h2>
        <div className="flex items-center gap-2 text-lg font-mono bg-gray-800 px-3 py-1 rounded-md text-red-400">
          <ClockIcon className="w-6 h-6" />
          <span>{String(minutes).padStart(2, '0')}:{String(seconds).padStart(2, '0')}</span>
        </div>
      </div>

      <div className="mb-6">
        <p className="text-gray-400 mb-2">Question {currentQuestionIndex + 1} of {mcqs.length}</p>
        <p className="font-semibold text-gray-200 text-lg">{currentQuestion.question}</p>
      </div>

      <div className="space-y-3 mb-6">
        {currentQuestion.options.map((option, index) => (
          <button
            key={index}
            onClick={() => handleSelectAnswer(option)}
            className={`w-full text-left p-3 rounded-lg border-2 transition-colors duration-200 ${
              selectedAnswers[currentQuestionIndex] === option
                ? 'bg-indigo-600 border-indigo-500 text-white'
                : 'bg-gray-800 border-gray-600 hover:bg-gray-600'
            }`}
          >
            {option}
          </button>
        ))}
      </div>

      <div className="flex justify-between items-center">
        <button
          onClick={handlePrev}
          disabled={currentQuestionIndex === 0}
          className="px-4 py-2 bg-gray-600 rounded-md hover:bg-gray-500 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Previous
        </button>
        {currentQuestionIndex === mcqs.length - 1 ? (
          <button
            onClick={handleFinishQuiz}
            className="px-6 py-2 bg-green-600 rounded-md hover:bg-green-500 font-bold"
          >
            Finish Quiz
          </button>
        ) : (
          <button
            onClick={handleNext}
            disabled={currentQuestionIndex === mcqs.length - 1}
            className="px-6 py-2 bg-indigo-600 rounded-md hover:bg-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Next
          </button>
        )}
      </div>
    </div>
  );
};

export default QuizView;

import React from 'react';
import { MCQ, QuizResult } from '../types';
import { CheckCircleIcon, XCircleIcon } from './icons';

interface QuizResultsViewProps {
  mcqs: MCQ[];
  result: QuizResult;
  onRetake: () => void;
  onBackToStudyGuide: () => void;
}

const QuizResultsView: React.FC<QuizResultsViewProps> = ({ mcqs, result, onRetake, onBackToStudyGuide }) => {
  return (
    <div className="bg-gray-700 p-6 rounded-lg shadow-lg animate-fade-in">
      <h2 className="text-3xl font-bold text-center text-indigo-300 mb-2">Quiz Complete!</h2>
      <p className="text-center text-xl text-gray-200 mb-6">
        You scored <span className="font-bold text-2xl text-white">{result.score}</span> out of <span className="font-bold text-2xl text-white">{mcqs.length}</span>
      </p>

      <div className="space-y-4 mb-6">
        {mcqs.map((mcq, index) => {
          const userAnswer = result.answers[index];
          const isCorrect = userAnswer === mcq.correctAnswer;
          return (
            <div key={index} className="bg-gray-800 p-4 rounded-lg">
              <p className="font-semibold text-gray-300 mb-2">{index + 1}. {mcq.question}</p>
              <p className={`flex items-center gap-2 text-sm ${isCorrect ? 'text-green-400' : 'text-red-400'}`}>
                {isCorrect ? <CheckCircleIcon className="w-5 h-5" /> : <XCircleIcon className="w-5 h-5" />}
                Your answer: <span className="font-medium">{userAnswer || 'Not answered'}</span>
              </p>
              {!isCorrect && (
                <p className="flex items-center gap-2 text-sm text-green-400 mt-1">
                  <CheckCircleIcon className="w-5 h-5" />
                  Correct answer: <span className="font-medium">{mcq.correctAnswer}</span>
                </p>
              )}
            </div>
          );
        })}
      </div>

      <div className="flex justify-center gap-4">
        <button onClick={onBackToStudyGuide} className="px-4 py-2 bg-gray-600 rounded-md hover:bg-gray-500">
          Back to Study Guide
        </button>
        <button onClick={onRetake} className="px-6 py-2 bg-indigo-600 rounded-md hover:bg-indigo-500 font-bold">
          Retake Quiz
        </button>
      </div>
    </div>
  );
};

export default QuizResultsView;

import React, { useState, useCallback, useRef } from 'react';
import { EducationalContent, Difficulty, QuizResult, MCQ } from './types';
import { generateEducationalContentFromImage } from './services/geminiService';
import QuestionAccordion from './components/QuestionAccordion';
import MCQItem from './components/MCQItem';
import Flashcard from './components/Flashcard';
import QuizView from './components/QuizView';
import QuizResultsView from './components/QuizResultsView';
import { CameraIcon, SparklesIcon, XCircleIcon } from './components/icons';

type LoadingState = 'idle' | 'processing' | 'success' | 'error';
const difficultyLevels: Difficulty[] = ['Easy', 'Medium', 'Hard', 'Competitive Exam'];

const App: React.FC = () => {
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [educationalContent, setEducationalContent] = useState<EducationalContent | null>(null);
  const [loadingState, setLoadingState] = useState<LoadingState>('idle');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [difficulty, setDifficulty] = useState<Difficulty>('Medium');
  const [isQuizActive, setIsQuizActive] = useState(false);
  const [quizResult, setQuizResult] = useState<QuizResult | null>(null);


  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      processFile(file);
    }
  };

  const processFile = (file: File) => {
    setImageFile(file);
    const reader = new FileReader();
    reader.onload = (e) => {
      setImageUrl(e.target?.result as string);
      setEducationalContent(null);
      setLoadingState('idle');
      setErrorMessage(null);
      setIsQuizActive(false);
      setQuizResult(null);
    };
    reader.readAsDataURL(file);
  };

  const handleDrop = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.remove('border-indigo-500');
    const file = event.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) {
        processFile(file);
    }
  };

  const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
  };

  const handleDragEnter = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.add('border-indigo-500');
  };

  const handleDragLeave = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.remove('border-indigo-500');
  };

  const handleSubmit = useCallback(async () => {
    if (!imageUrl) return;

    setLoadingState('processing');
    setErrorMessage(null);
    setEducationalContent(null);
    setIsQuizActive(false);
    setQuizResult(null);

    try {
      const base64Data = imageUrl.split(',')[1];
      const result = await generateEducationalContentFromImage(base64Data, imageFile?.type || 'image/jpeg', difficulty);
      setEducationalContent(result);
      setLoadingState('success');
    } catch (error) {
      console.error(error);
      setErrorMessage(error instanceof Error ? error.message : 'An unknown error occurred.');
      setLoadingState('error');
    }
  }, [imageUrl, imageFile, difficulty]);

  const handleReset = () => {
    setImageFile(null);
    setImageUrl(null);
    setEducationalContent(null);
    setLoadingState('idle');
    setErrorMessage(null);
    setDifficulty('Medium');
    setIsQuizActive(false);
    setQuizResult(null);
    if(fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleQuizComplete = (answers: (string | null)[]) => {
    if (!educationalContent) return;
    const score = answers.reduce((acc, answer, index) => {
      if (answer === educationalContent.multipleChoiceQuestions[index].correctAnswer) {
        return acc + 1;
      }
      return acc;
    }, 0);
    setQuizResult({ score, answers });
    setIsQuizActive(false);
  };

  const startQuiz = () => {
    setQuizResult(null);
    setIsQuizActive(true);
  };

  const renderContent = () => {
    if (isQuizActive && educationalContent?.multipleChoiceQuestions) {
        return <QuizView mcqs={educationalContent.multipleChoiceQuestions} onQuizComplete={handleQuizComplete} />;
    }

    if (quizResult && educationalContent?.multipleChoiceQuestions) {
        return (
            <QuizResultsView
                mcqs={educationalContent.multipleChoiceQuestions}
                result={quizResult}
                onRetake={startQuiz}
                onBackToStudyGuide={() => setQuizResult(null)}
            />
        );
    }

    if (loadingState === 'processing') {
      return (
        <div className="flex flex-col items-center justify-center h-full text-center">
          <div className="w-12 h-12 border-4 border-t-indigo-500 border-gray-600 rounded-full animate-spin mb-4"></div>
          <p className="text-lg font-semibold text-gray-300">Creating your study guide...</p>
          <p className="text-gray-400">This might take a moment.</p>
        </div>
      );
    }

    if (loadingState === 'error') {
      return (
        <div className="flex items-center justify-center h-full text-center bg-red-900 bg-opacity-30 p-4 rounded-lg">
          <div>
