import { GoogleGenAI, Type, Modality } from "@google/genai";
import { EducationalContent, Difficulty } from '../types';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable is not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const educationalContentSchema = {
    type: Type.OBJECT,
    properties: {
        topicSummary: {
            type: Type.STRING,
            description: "A summary of the main topic from the text."
        },
        mindMapOutline: {
            type: Type.STRING,
            description: "A hierarchical mind map outline of the topic using nested bullet points."
        },
        revisionNotes: {
            type: Type.STRING,
            description: "A concise, one-page summary with only the most critical key points, definitions, and formulas, formatted with bullet points for quick revision."
        },
        shortAnswerQuestions: {
            type: Type.ARRAY,
            description: "Exactly 5 short answer questions.",
            items: {
                type: Type.OBJECT,
                properties: {
                    question: { type: Type.STRING },
                    answer: { type: Type.STRING }
                },
                required: ["question", "answer"]
            }
        },
        longAnswerQuestions: {
            type: Type.ARRAY,
            description: "Exactly 5 long answer questions.",
            items: {
                type: Type.OBJECT,
                properties: {
                    question: { type: Type.STRING },
                    answer: { type: Type.STRING }
                },
                required: ["question", "answer"]
            }
        },
        multipleChoiceQuestions: {
            type: Type.ARRAY,
            description: "Exactly 5 multiple choice questions.",
            items: {
                type: Type.OBJECT,
                properties: {
                    question: { type: Type.STRING },
                    options: {
                        type: Type.ARRAY,
                        description: "An array of 4 possible string answers.",
                        items: { type: Type.STRING }
                    },
                    correctAnswer: {
                        type: Type.STRING,
                        description: "The correct answer from the options list."
                    }
                },
                required: ["question", "options", "correctAnswer"]
            }
        },
        formulaExplanations: {
            type: Type.ARRAY,
            description: "Step-by-step explanations for any formulas found. This can be empty if no formulas are present.",
            items: {
                type: Type.OBJECT,
                properties: {
                    formula: { type: Type.STRING },
                    explanation: { type: Type.STRING }
                },
                required: ["formula", "explanation"]
            }
        },
        flashcards: {
            type: Type.ARRAY,
            description: "Exactly 10 flashcards based on key concepts.",
            items: {
                type: Type.OBJECT,
                properties: {
                    question: { type: Type.STRING, description: "The front of the flashcard." },
                    answer: { type: Type.STRING, description: "The back of the flashcard." }
                },
                required: ["question", "answer"]
            }
        }
    },
    required: ["topicSummary", "mindMapOutline", "revisionNotes", "shortAnswerQuestions", "longAnswerQuestions", "multipleChoiceQuestions", "formulaExplanations", "flashcards"]
};

const getDifficultyInstructions = (difficulty: Difficulty): string => {
    switch (difficulty) {
        case 'Easy':
            return "Adjust the question complexity to an 'Easy' level. Questions should be straightforward and test direct recall of information from the text.";
        case 'Medium':
            return "Adjust the question complexity to a 'Medium' level. Questions should test comprehension and basic application of concepts.";
        case 'Hard':
            return "Adjust the question complexity to a 'Hard' level. Questions must require inference, analysis, and application. Include several HOTS (Higher Order Thinking Skills) questions that ask 'why' and 'how' and require critical thinking.";
        case 'Competitive Exam':
            return "Adjust the question complexity to a 'Competitive Exam' level. Questions should be challenging, potentially multi-step, and require deep conceptual understanding and application, similar to what might be found in a university entrance exam.";
        default:
            return '';
    }
};

export async function generateEducationalContentFromImage(base64ImageData: string, mimeType: string, difficulty: Difficulty): Promise<EducationalContent> {
    const imagePart = {
        inlineData: {
            data: base64ImageData,
            mimeType: mimeType,
        },
    };

    const difficultyInstructions = getDifficultyInstructions(difficulty);

    const textPart = {
        text: `You are an advanced educational AI. Your first and most important task is to carefully analyze the provided image of a textbook page or notes and extract the text.

        **Image Analysis Rules:**
        - If parts of the text are unclear or obscured, try to logically reconstruct incomplete words based on context.
        - Ignore any irrelevant marks, scribbles, or artifacts on the page.
        - It is crucial that you do not invent or hallucinate any content that is not present in the image.
        - If the text is completely unreadable and you cannot extract any meaningful content, you must still adhere to the JSON output format. For the 'topicSummary', you must provide a polite message explaining the issue (e.g., "The text in the image is too blurry to read. Please upload a clearer picture."). For all question/flashcard arrays, you must still provide the required number of items, but they can be placeholders acknowledging the unreadable text.

        **Study Guide Generation:**
        Once you have analyzed the text, perform the following tasks:
        1. Summarize the main topic in a concise paragraph.
        2. Convert the topic into a structured mind map outline using a nested bullet point hierarchy.
        3. Create a 'Quick Revision Notes' section. This should be a concise, one-page summary highlighting only the most critical key points, definitions, and formulas from the text. Use bullet points for clarity.
        4. Generate exactly 10 flashcards (simple question/answer pairs) covering the key concepts.
        5. Generate exactly 5 short answer questions based on the text.
        6. Generate exactly 5 long answer questions that require more detailed explanation.
        7. Generate exactly 5 multiple choice questions, each with 4 distinct options.
        8. Provide clear, student-friendly answers for all questions.
        9. If the page contains any mathematical or scientific formulas, identify them and explain each one step-by-step. If there are no formulas, this section must be an empty array.
        10. Ensure the language used is simple and suitable for students aged 12–18.

        ${difficultyInstructions}

        Provide the output in a structured JSON format according to the provided schema.`,
    };

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: [imagePart, textPart] },
            config: {
                responseMimeType: "application/json",
                responseSchema: educationalContentSchema,
            },
        });

        const jsonText = response.text;
        if (!jsonText) {
            throw new Error("API returned an empty response.");
        }

        const parsedJson = JSON.parse(jsonText);
        return parsedJson as EducationalContent;

    } catch (error) {
        console.error("Error calling Gemini API:", error);
        throw new Error("Failed to generate educational content from the image. Please check the console for details.");
    }
}


export async function generateSpeech(text: string): Promise<string> {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' },
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

        if (!base64Audio) {
            throw new Error("No audio data returned from the API.");
        }

        return base64Audio;
    } catch (error) {
        console.error("Error generating speech:", error);
        throw new Error("Failed to generate speech. Please check the console for details.");
    }
}

import React, { useState, useCallback, useRef } from 'react';
import { EducationalContent, Difficulty, QuizResult, MCQ } from './types';
import { generateEducationalContentFromImage } from './services/geminiService';
import QuestionAccordion from './components/QuestionAccordion';
import MCQItem from './components/MCQItem';
import Flashcard from './components/Flashcard';
import QuizView from './components/QuizView';
import QuizResultsView from './components/QuizResultsView';
import { CameraIcon, SparklesIcon, XCircleIcon } from './components/icons';

type LoadingState = 'idle' | 'processing' | 'success' | 'error';
const difficultyLevels: Difficulty[] = ['Easy', 'Medium', 'Hard', 'Competitive Exam'];

const App: React.FC = () => {
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [educationalContent, setEducationalContent] = useState<EducationalContent | null>(null);
  const [loadingState, setLoadingState] = useState<LoadingState>('idle');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [difficulty, setDifficulty] = useState<Difficulty>('Medium');
  const [isQuizActive, setIsQuizActive] = useState(false);
  const [quizResult, setQuizResult] = useState<QuizResult | null>(null);


  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      processFile(file);
    }
  };

  const processFile = (file: File) => {
    setImageFile(file);
    const reader = new FileReader();
    reader.onload = (e) => {
      setImageUrl(e.target?.result as string);
      setEducationalContent(null);
      setLoadingState('idle');
      setErrorMessage(null);
      setIsQuizActive(false);
      setQuizResult(null);
    };
    reader.readAsDataURL(file);
  };

  const handleDrop = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.remove('border-indigo-500');
    const file = event.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) {
        processFile(file);
    }
  };

  const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
  };

  const handleDragEnter = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.add('border-indigo-500');
  };

  const handleDragLeave = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.remove('border-indigo-500');
  };

  const handleSubmit = useCallback(async () => {
    if (!imageUrl) return;

    setLoadingState('processing');
    setErrorMessage(null);
    setEducationalContent(null);
    setIsQuizActive(false);
    setQuizResult(null);

    try {
      const base64Data = imageUrl.split(',')[1];
      const result = await generateEducationalContentFromImage(base64Data, imageFile?.type || 'image/jpeg', difficulty);
      setEducationalContent(result);
      setLoadingState('success');
    } catch (error) {
      console.error(error);
      setErrorMessage(error instanceof Error ? error.message : 'An unknown error occurred.');
      setLoadingState('error');
    }
  }, [imageUrl, imageFile, difficulty]);

  const handleReset = () => {
    setImageFile(null);
    setImageUrl(null);
    setEducationalContent(null);
    setLoadingState('idle');
    setErrorMessage(null);
    setDifficulty('Medium');
    setIsQuizActive(false);
    setQuizResult(null);
    if(fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleQuizComplete = (answers: (string | null)[]) => {
    if (!educationalContent) return;
    const score = answers.reduce((acc, answer, index) => {
      if (answer === educationalContent.multipleChoiceQuestions[index].correctAnswer) {
        return acc + 1;
      }
      return acc;
    }, 0);
    setQuizResult({ score, answers });
    setIsQuizActive(false);
  };

  const startQuiz = () => {
    setQuizResult(null);
    setIsQuizActive(true);
  };

  const renderContent = () => {
    if (isQuizActive && educationalContent?.multipleChoiceQuestions) {
        return <QuizView mcqs={educationalContent.multipleChoiceQuestions} onQuizComplete={handleQuizComplete} />;
    }

    if (quizResult && educationalContent?.multipleChoiceQuestions) {
        return (
            <QuizResultsView
                mcqs={educationalContent.multipleChoiceQuestions}
                result={quizResult}
                onRetake={startQuiz}
                onBackToStudyGuide={() => setQuizResult(null)}
            />
        );
    }

    if (loadingState === 'processing') {
      return (
        <div className="flex flex-col items-center justify-center h-full text-center">
          <div className="w-12 h-12 border-4 border-t-indigo-500 border-gray-600 rounded-full animate-spin mb-4"></div>
          <p className="text-lg font-semibold text-gray-300">Creating your study guide...</p>
          <p className="text-gray-400">This might take a moment.</p>
        </div>
      );
    }

    if (loadingState === 'error') {
      return (
        <div className="flex items-center justify-center h-full text-center bg-red-900 bg-opacity-30 p-4 rounded-lg">
          <div>
            <XCircleIcon className="w-12 h-12 text-red-400 mx-auto mb-2" />
            <p className="text-red-400 font-semibold">An error occurred</p>
            <p className="text-red-300 text-sm">{errorMessage}</p>
          </div>
        </div>
      );
    }

    if (loadingState === 'success' && educationalContent) {
      return (
        <div className="space-y-8 overflow-y-auto max-h-[80vh] pr-2">
          <section>
            <h3 className="text-2xl font-bold mb-3 text-gray-200">📘 Topic Summary</h3>
            <div className="bg-gray-700 p-4 rounded-lg text-gray-300 whitespace-pre-wrap">{educationalContent.topicSummary}</div>
          </section>

          {educationalContent.mindMapOutline && (
            <section>
              <h3 className="text-2xl font-bold mb-3 text-gray-200">🗺️ Mind Map Outline</h3>
              <div className="bg-gray-700 p-4 rounded-lg text-gray-300">
                  <pre className="whitespace-pre-wrap font-sans">{educationalContent.mindMapOutline}</pre>
              </div>
            </section>
          )}

          {educationalContent.revisionNotes && (
            <section>
              <h3 className="text-2xl font-bold mb-3 text-gray-200">⚡ Quick Revision Notes</h3>
              <div className="bg-gray-700 p-4 rounded-lg text-gray-300">
                  <pre className="whitespace-pre-wrap font-sans">{educationalContent.revisionNotes}</pre>
              </div>
            </section>
          )}

          {educationalContent.formulaExplanations?.length > 0 && (
            <section>
              <h3 className="text-2xl font-bold mb-3 text-gray-200">🔬 Formula Explanations</h3>
              <div className="space-y-3">
                {educationalContent.formulaExplanations.map((item, index) => (
                  <div key={index} className="bg-gray-700 p-4 rounded-lg">
                      <p className="font-mono text-indigo-300 text-lg mb-2">{item.formula}</p>
                      <p className="text-gray-300 whitespace-pre-wrap">{item.explanation}</p>
                  </div>
                ))}
              </div>
            </section>
          )}

          {educationalContent.flashcards?.length > 0 && (
              <section>
                  <h3 className="text-2xl font-bold mb-3 text-gray-200">🃏 Flashcards</h3>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      {educationalContent.flashcards.map((card, index) => (
                          <Flashcard key={`flashcard-${index}`} flashcard={card} />
                      ))}
                  </div>
              </section>
          )}

          <section>
            <h3 className="text-2xl font-bold mb-3 text-gray-200">📝 Short Answer Questions</h3>
            <div className="space-y-3">
              {educationalContent.shortAnswerQuestions.map((pair, index) => (
                <QuestionAccordion key={`short-${index}`} qaPair={pair} />
              ))}
            </div>
          </section>

          <section>
            <h3 className="text-2xl font-bold mb-3 text-gray-200">📖 Long Answer Questions</h3>
            <div className="space-y-3">
              {educationalContent.longAnswerQuestions.map((pair, index) => (
                <QuestionAccordion key={`long-${index}`} qaPair={pair} />
              ))}
            </div>
          </section>

          <section>
            <h3 className="text-2xl font-bold mb-3 text-gray-200">🧠 Multiple Choice Questions</h3>
            <div className="space-y-3">
              {educationalContent.multipleChoiceQuestions.map((mcq, index) => (
                <MCQItem key={`mcq-${index}`} mcq={mcq} />
              ))}
            </div>
             <button
                onClick={startQuiz}
                className="mt-6 w-full bg-green-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-green-700 transition-colors duration-300"
              >
                Start Timed Quiz
              </button>
          </section>
        </div>
      );
    }

    return null;
  }

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 flex flex-col items-center p-4 sm:p-6 lg:p-8">
      <div className="w-full max-w-4xl mx-auto">
        <header className="text-center mb-8">
          <h1 className="text-4xl sm:text-5xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-indigo-600">
            AI Study Buddy
          </h1>
          <p className="mt-2 text-lg text-gray-400">
            Upload a page of notes, and let AI create a study guide for you.
          </p>
        </header>

        <main className="bg-gray-800 rounded-2xl shadow-2xl p-6">
          {!imageUrl ? (
            <div 
              className="w-full h-64 border-4 border-dashed border-gray-600 rounded-xl flex flex-col justify-center items-center text-center cursor-pointer hover:border-indigo-500 transition-colors duration-300"
              onClick={() => fileInputRef.current?.click()}
              onDrop={handleDrop}
              onDragOver={handleDragOver}
              onDragEnter={handleDragEnter}
              onDragLeave={handleDragLeave}
            >
              <CameraIcon className="w-16 h-16 text-gray-500 mb-4" />
              <h2 className="text-xl font-semibold text-gray-300">Upload an Image</h2>
              <p className="text-gray-400">Click to browse or drag & drop an image here</p>
              <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileChange}
                accept="image/*"
                className="hidden"
              />
            </div>
          ) : (
            <div className="flex flex-col lg:flex-row gap-6">
              <div className="lg:w-1/2 flex-shrink-0">
                <div className="relative group">
                  <img src={imageUrl} alt="Uploaded page" className="w-full h-auto object-contain rounded-lg shadow-lg max-h-[60vh]" />
                  <button onClick={handleReset} className="absolute top-2 right-2 p-2 bg-black bg-opacity-50 rounded-full text-white hover:bg-opacity-75 transition-all opacity-0 group-hover:opacity-100 focus:opacity-100">
                    <XCircleIcon className="w-6 h-6" />
                  </button>
                </div>

                <div className="mt-4">
                    <label className="block text-sm font-medium text-gray-300 mb-2">Select Difficulty</label>
                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                        {difficultyLevels.map((level) => (
                            <button key={level} onClick={() => setDifficulty(level)} className={`px-4 py-2 text-sm font-semibold rounded-md transition-colors duration-200 ${difficulty === level ? 'bg-indigo-600 text-white' : 'bg-gray-700 hover:bg-gray-600'}`}>
                                {level}
                            </button>
                        ))}
                    </div>
                </div>

                {loadingState !== 'processing' && (
                  <button
                    onClick={handleSubmit}
                    disabled={loadingState === 'processing'}
                    className="mt-4 w-full bg-indigo-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-colors duration-300 disabled:bg-gray-500 disabled:cursor-not-allowed"
                  >
                    <SparklesIcon className="w-6 h-6" />
                    Generate Study Guide
                  </button>
                )}
              </div>
              <div className="lg:w-1/2 flex flex-col">
                {renderContent()}
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

