import { GoogleGenAI, Type, Modality } from "@google/genai";
import { EducationalContent, Difficulty } from '../types';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable is not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const educationalContentSchema = {
    type: Type.OBJECT,
    properties: {
        topicSummary: {
            type: Type.STRING,
            description: "A summary of the main topic from the text."
        },
        mindMapOutline: {
            type: Type.STRING,
            description: "A hierarchical mind map outline of the topic using nested bullet points."
        },
        revisionNotes: {
            type: Type.STRING,
            description: "A concise, one-page summary with only the most critical key points, definitions, and formulas, formatted with bullet points for quick revision."
        },
        shortAnswerQuestions: {
            type: Type.ARRAY,
            description: "Exactly 5 short answer questions.",
            items: {
                type: Type.OBJECT,
                properties: {
                    question: { type: Type.STRING },
                    answer: { type: Type.STRING }
                },
                required: ["question", "answer"]
            }
        },
        longAnswerQuestions: {
            type: Type.ARRAY,
            description: "Exactly 5 long answer questions.",
            items: {
                type: Type.OBJECT,
                properties: {
                    question: { type: Type.STRING },
                    answer: { type: Type.STRING }
                },
                required: ["question", "answer"]
            }
        },
        multipleChoiceQuestions: {
            type: Type.ARRAY,
            description: "Exactly 5 multiple choice questions.",
            items: {
                type: Type.OBJECT,
                properties: {
                    question: { type: Type.STRING },
                    options: {
                        type: Type.ARRAY,
                        description: "An array of 4 possible string answers.",
                        items: { type: Type.STRING }
                    },
                    correctAnswer: {
                        type: Type.STRING,
                        description: "The correct answer from the options list."
                    }
                },
                required: ["question", "options", "correctAnswer"]
            }
        },
        formulaExplanations: {
            type: Type.ARRAY,
            description: "Step-by-step explanations for any formulas found. This can be empty if no formulas are present.",
            items: {
                type: Type.OBJECT,
                properties: {
                    formula: { type: Type.STRING },
                    explanation: { type: Type.STRING }
                },
                required: ["formula", "explanation"]
            }
        },
        flashcards: {
            type: Type.ARRAY,
            description: "Exactly 10 flashcards based on key concepts.",
            items: {
                type: Type.OBJECT,
                properties: {
                    question: { type: Type.STRING, description: "The front of the flashcard." },
                    answer: { type: Type.STRING, description: "The back of the flashcard." }
                },
                required: ["question", "answer"]
            }
        }
    },
    required: ["topicSummary", "mindMapOutline", "revisionNotes", "shortAnswerQuestions", "longAnswerQuestions", "multipleChoiceQuestions", "formulaExplanations", "flashcards"]
};

const getDifficultyInstructions = (difficulty: Difficulty): string => {
    switch (difficulty) {
        case 'Easy':
            return "Adjust the question complexity to an 'Easy' level. Questions should be straightforward and test direct recall of information from the text.";
        case 'Medium':
            return "Adjust the question complexity to a 'Medium' level. Questions should test comprehension and basic application of concepts.";
        case 'Hard':
            return "Adjust the question complexity to a 'Hard' level. Questions must require inference, analysis, and application. Include several HOTS (Higher Order Thinking Skills) questions that ask 'why' and 'how' and require critical thinking.";
        case 'Competitive Exam':
            return "Adjust the question complexity to a 'Competitive Exam' level. Questions should be challenging, potentially multi-step, and require deep conceptual understanding and application, similar to what might be found in a university entrance exam.";
        default:
            return '';
    }
};

export async function generateEducationalContentFromImage(base64ImageData: string, mimeType: string, difficulty: Difficulty): Promise<EducationalContent> {
    const imagePart = {
        inlineData: {
            data: base64ImageData,
            mimeType: mimeType,
        },
    };

    const difficultyInstructions = getDifficultyInstructions(difficulty);

    const textPart = {
        text: `You are an advanced educational AI. Your first and most important task is to carefully analyze the provided image of a textbook page or notes and extract the text.

        **Image Analysis Rules:**
        - If parts of the text are unclear or obscured, try to logically reconstruct incomplete words based on context.
        - Ignore any irrelevant marks, scribbles, or artifacts on the page.
        - It is crucial that you do not invent or hallucinate any content that is not present in the image.
        - If the text is completely unreadable and you cannot extract any meaningful content, you must still adhere to the JSON output format. For the 'topicSummary', you must provide a polite message explaining the issue (e.g., "The text in the image is too blurry to read. Please upload a clearer picture."). For all question/flashcard arrays, you must still provide the required number of items, but they can be placeholders acknowledging the unreadable text.

        **Study Guide Generation:**
        Once you have analyzed the text, perform the following tasks:
        1. Summarize the main topic in a concise paragraph.
        2. Convert the topic into a structured mind map outline using a nested bullet point hierarchy.
        3. Create a 'Quick Revision Notes' section. This should be a concise, one-page summary highlighting only the most critical key points, definitions, and formulas from the text. Use bullet points for clarity.
        4. Generate exactly 10 flashcards (simple question/answer pairs) covering the key concepts.
        5. Generate exactly 5 short answer questions based on the text.
        6. Generate exactly 5 long answer questions that require more detailed explanation.
        7. Generate exactly 5 multiple choice questions, each with 4 distinct options.
        8. Provide clear, student-friendly answers for all questions.
        9. If the page contains any mathematical or scientific formulas, identify them and explain each one step-by-step. If there are no formulas, this section must be an empty array.
        10. Ensure the language used is simple and suitable for students aged 12–18.

        ${difficultyInstructions}

        Provide the output in a structured JSON format according to the provided schema.`,
    };

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: [imagePart, textPart] },
            config: {
                responseMimeType: "application/json",
                responseSchema: educationalContentSchema,
            },
        });

        const jsonText = response.text;
        if (!jsonText) {
            throw new Error("API returned an empty response.");
        }

        const parsedJson = JSON.parse(jsonText);
        return parsedJson as EducationalContent;

    } catch (error) {
        console.error("Error calling Gemini API:", error);
        throw new Error("Failed to generate educational content from the image. Please check the console for details.");
    }
}


export async function generateSpeech(text: string): Promise<string> {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' },
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

        if (!base64Audio) {
            throw new Error("No audio data returned from the API.");
        }

        return base64Audio;
    } catch (error) {
        console.error("Error generating speech:", error);
        throw new Error("Failed to generate speech. Please check the console for details.");
    }
}

export async function translateText(text: string, targetLanguage: string): Promise<string> {
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Translate the following text to ${targetLanguage}. Do not add any extra commentary, introductory phrases, or explanations. Only provide the direct translation of the text itself.\n\nText: "${text}"`,
        });

        const translatedText = response.text;
        if (!translatedText) {
            throw new Error("API returned an empty response for translation.");
        }
        return translatedText.trim();
    } catch (error) {
        console.error(`Error translating text to ${targetLanguage}:`, error);
        throw new Error(`Failed to translate text. Please try again.`);
    }
}

import React, { useState, useRef } from 'react';
import { generateSpeech } from '../services/geminiService';
import { decode, decodeAudioData } from '../utils/audioUtils';
import { SpeakerWaveIcon, SpeakerXMarkIcon, XCircleIcon } from './icons';

interface TextToSpeechButtonProps {
  textToSpeak: string;
}

const TextToSpeechButton: React.FC<TextToSpeechButtonProps> = ({ textToSpeak }) => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [audioError, setAudioError] = useState<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<AudioBufferSourceNode | null>(null);

  const handlePlayAudio = async () => {
    setAudioError(null);

    if (isPlaying && sourceRef.current) {
        sourceRef.current.stop();
        setIsPlaying(false);
        return;
    }

    setIsGenerating(true);
    try {
        const audioBase64 = await generateSpeech(textToSpeak);

        if (!audioContextRef.current) {
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }
        const audioContext = audioContextRef.current;
        if(audioContext.state === 'suspended') {
          await audioContext.resume();
        }

        const audioBuffer = await decodeAudioData(decode(audioBase64), audioContext, 24000, 1);

        const source = audioContext.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(audioContext.destination);
        source.onended = () => {
            setIsPlaying(false);
            sourceRef.current = null;
        };
        source.start();
        sourceRef.current = source;
        setIsPlaying(true);
    } catch (error) {
        console.error("Failed to play audio:", error);
        setAudioError("Could not generate audio due to high demand. Please try again later.");
        setTimeout(() => setAudioError(null), 5000);
    } finally {
        setIsGenerating(false);
    }
  };

  return (
    <div className="mt-4">
        <button
        onClick={handlePlayAudio}
        disabled={isGenerating || !textToSpeak}
        className="flex items-center gap-2 text-sm text-indigo-400 hover:text-indigo-300 disabled:text-gray-500 disabled:cursor-wait"
        aria-label={isPlaying ? 'Stop reading' : 'Read aloud'}
        >
        {isGenerating ? (
            <>
            <div className="w-4 h-4 border-2 border-t-indigo-400 border-gray-600 rounded-full animate-spin"></div>
            Generating...
            </>
        ) : isPlaying ? (
            <>
            <SpeakerXMarkIcon className="w-5 h-5" />
            Stop
            </>
        ) : (
            <>
            <SpeakerWaveIcon className="w-5 h-5" />
            Read Aloud
            </>
        )}
        </button>
        {audioError && (
        <p className="mt-2 text-sm text-red-400 flex items-center gap-2">
            <XCircleIcon className="w-5 h-5" />
            <span>{audioError}</span>
        </p>
        )}
    </div>
  );
};

export default TextToSpeechButton;

import React, { useState, useEffect, useMemo } from 'react';
import { QA_Pair } from '../types';
import { translateText } from '../services/geminiService';
import { ChevronDownIcon, GlobeAltIcon } from './icons';
import TextToSpeechButton from './TextToSpeechButton';

interface QuestionAccordionProps {
  qaPair: QA_Pair;
}

type Language = 'English' | 'Hindi' | 'Bengali';

const QuestionAccordion: React.FC<QuestionAccordionProps> = ({ qaPair }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [selectedLanguage, setSelectedLanguage] = useState<Language>('English');
  const [isTranslating, setIsTranslating] = useState(false);
  const [translatedContent, setTranslatedContent] = useState<QA_Pair | null>(null);

  const originalContent = useMemo(() => qaPair, [qaPair]);

  useEffect(() => {
    // Reset state if the underlying qaPair changes
    setSelectedLanguage('English');
    setTranslatedContent(null);
    setIsTranslating(false);
  }, [qaPair]);

  const handleLanguageChange = async (lang: Language) => {
    setSelectedLanguage(lang);
    if (lang === 'English') {
      setTranslatedContent(null);
      return;
    }

    // Check cache first
    if (translatedContent && translatedContent.question.startsWith(`[${lang}]`)) {
        return;
    }

    setIsTranslating(true);
    try {
      const [translatedQuestion, translatedAnswer] = await Promise.all([
        translateText(originalContent.question, lang),
        translateText(originalContent.answer, lang)
      ]);
      setTranslatedContent({ question: `[${lang}]` + translatedQuestion, answer: translatedAnswer });
    } catch (error) {
      console.error("Translation failed:", error);
      // Optionally show an error message to the user
      setSelectedLanguage('English'); // Revert on failure
    } finally {
      setIsTranslating(false);
    }
  };

  const displayContent = selectedLanguage === 'English' ? originalContent : (translatedContent || originalContent);

  return (
    <details className="group bg-gray-700 rounded-lg overflow-hidden transition-all duration-300" onToggle={(e) => setIsOpen((e.target as HTMLDetailsElement).open)}>
      <summary className="p-4 flex justify-between items-center cursor-pointer list-none hover:bg-gray-600">
        <span className="font-semibold text-gray-200">{displayContent.question.replace(/\[(Hindi|Bengali)\]/g, '')}</span>
        <ChevronDownIcon className="w-5 h-5 text-gray-400 transition-transform duration-300 group-open:rotate-180" />
      </summary>
      <div className="p-4 border-t border-gray-600 bg-gray-800">
        <p className="text-gray-300 whitespace-pre-wrap">{isTranslating ? 'Translating...' : displayContent.answer}</p>

        <div className="mt-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
            <TextToSpeechButton textToSpeak={displayContent.answer} />

            {isOpen && (
                <div className="flex items-center gap-2">
                    <GlobeAltIcon className="w-5 h-5 text-gray-400"/>
                    <select
                        value={selectedLanguage}
                        onChange={(e) => handleLanguageChange(e.target.value as Language)}
                        disabled={isTranslating}
                        className="bg-gray-700 border border-gray-600 text-white text-sm rounded-lg focus:ring-indigo-500 focus:border-indigo-500 p-1.5"
                    >
                        <option>English</option>
                        <option>Hindi</option>
                        <option>Bengali</option>
                    </select>
                </div>
            )}
        </div>
      </div>
    </details>
  );
};

export default QuestionAccordion;

