const App: React.FC = () => {
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [educationalContent, setEducationalContent] = useState<EducationalContent | null>(null);
  const [loadingState, setLoadingState] = useState<LoadingState>('idle');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [difficulty, setDifficulty] = useState<Difficulty>('Medium');
  const [isQuizActive, setIsQuizActive] = useState(false);
  const [quizResult, setQuizResult] = useState<QuizResult | null>(null);
  const [isExportingPdf, setIsExportingPdf] = useState(false);
  const [showProgressView, setShowProgressView] = useState(false);
  const [progressData, setProgressData] = useState<ProgressRecord[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    try {
        const storedProgress = localStorage.getItem(PROGRESS_STORAGE_KEY);
        if (storedProgress) {
            setProgressData(JSON.parse(storedProgress));
        }
    } catch (error) {
        console.error("Failed to load progress data:", error);
        setProgressData([]);
    }
  }, []);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      processFile(file);
    }
  };

  const processFile = (file: File) => {
    setImageFile(file);
    const reader = new FileReader();
    reader.onload = (e) => {
      setImageUrl(e.target?.result as string);
      setEducationalContent(null);
      setLoadingState('idle');
      setErrorMessage(null);
      setIsQuizActive(false);
      setQuizResult(null);
    };
    reader.readAsDataURL(file);
  };

  const handleDrop = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.remove('border-indigo-500');
    const file = event.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) {
        processFile(file);
    }
  };

  const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
  };

  const handleDragEnter = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.add('border-indigo-500');
  };

  const handleDragLeave = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.remove('border-indigo-500');
  };

  const handleSubmit = useCallback(async () => {
    if (!imageUrl) return;

    setLoadingState('processing');
    setErrorMessage(null);
    setEducationalContent(null);
    setIsQuizActive(false);
    setQuizResult(null);

    try {
      const base64Data = imageUrl.split(',')[1];
      const result = await generateEducationalContentFromImage(base64Data, imageFile?.type || 'image/jpeg', difficulty);
      setEducationalContent(result);
      setLoadingState('success');
    } catch (error) {
      console.error(error);
      setErrorMessage(error instanceof Error ? error.message : 'An unknown error occurred.');
      setLoadingState('error');
    }
  }, [imageUrl, imageFile, difficulty]);

  const handleReset = () => {
    setImageFile(null);
    setImageUrl(null);
    setEducationalContent(null);
    setLoadingState('idle');
    setErrorMessage(null);
    setDifficulty('Medium');
    setIsQuizActive(false);
    setQuizResult(null);
    if(fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleQuizComplete = (answers: (string | null)[]) => {
    if (!educationalContent) return;
    const score = answers.reduce((acc, answer, index) => {
      if (answer === educationalContent.multipleChoiceQuestions[index].correctAnswer) {
        return acc + 1;
      }
      return acc;
    }, 0);
    setQuizResult({ score, answers });
    setIsQuizActive(false);

    // Save progress
    const newRecord: ProgressRecord = {
        topic: educationalContent.topicSummary.substring(0, 50) + '...', // Truncate for display
        score,
        total: educationalContent.multipleChoiceQuestions.length,
        date: new Date().toISOString(),
    };
    const updatedProgress = [newRecord, ...progressData];
    setProgressData(updatedProgress);
    localStorage.setItem(PROGRESS_STORAGE_KEY, JSON.stringify(updatedProgress));
  };

  const startQuiz = () => {
    setQuizResult(null);
    setIsQuizActive(true);
  };

  const handleExportPdf = async () => {
    if (!contentRef.current) return;
    setIsExportingPdf(true);
    try {
        const canvas = await html2canvas(contentRef.current, {
            scale: 2,
            backgroundColor: '#1f2937', // bg-gray-800
        });
        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF({
            orientation: 'p',
            unit: 'px',
            format: [canvas.width, canvas.height]
        });
        pdf.addImage(imgData, 'PNG', 0, 0, canvas.width, canvas.height);
        pdf.save('ai-study-buddy-guide.pdf');
    } catch (error) {
        console.error("Failed to export PDF:", error);
    } finally {
        setIsExportingPdf(false);
    }
  };

  const handleClearHistory = () => {
    setProgressData([]);
    localStorage.removeItem(PROGRESS_STORAGE_KEY);
  };

  const renderContent = () => {
    if (isQuizActive && educationalContent?.multipleChoiceQuestions) {
        return <QuizView mcqs={educationalContent.multipleChoiceQuestions} onQuizComplete={handleQuizComplete} />;
    }

    if (quizResult && educationalContent?.multipleChoiceQuestions) {
        return (
            <QuizResultsView
                mcqs={educationalContent.multipleChoiceQuestions}
                result={quizResult}
                onRetake={startQuiz}
                onBackToStudyGuide={() => setQuizResult(null)}
            />
        );
    }

    if (loadingState === 'processing') {
      return (
        <div className="flex flex-col items-center justify-center h-full text-center">
          <div className="w-12 h-12 border-4 border-t-indigo-500 border-gray-600 rounded-full animate-spin mb-4"></div>
          <p className="text-lg font-semibold text-gray-300">Creating your study guide...</p>
          <p className="text-gray-400">This might take a moment.</p>
        </div>
      );
    }

    if (loadingState === 'error') {
      return (
        <div className="flex items-center justify-center h-full text-center bg-red-900 bg-opacity-30 p-4 rounded-lg">
          <div>
            <XCircleIcon className="w-12 h-12 text-red-400 mx-auto mb-2" />
            <p className="text-red-400 font-semibold">An error occurred</p>
            <p className="text-red-300 text-sm">{errorMessage}</p>
          </div>
        </div>
      );
    }

    if (loadingState === 'success' && educationalContent) {
      return (
        <div ref={contentRef} className="space-y-8 overflow-y-auto max-h-[80vh] p-2">
          <section>
            <h3 className="text-2xl font-bold mb-3 text-gray-200">📘 Topic Summary</h3>
            <div className="bg-gray-700 p-4 rounded-lg text-gray-300">
                <p className="whitespace-pre-wrap">{educationalContent.topicSummary}</p>
                <TextToSpeechButton textToSpeak={educationalContent.topicSummary} />
            </div>
          </section>

          {educationalContent.mindMapOutline && (
            <section>
              <h3 className="text-2xl font-bold mb-3 text-gray-200">🗺️ Mind Map Outline</h3>
              <div className="bg-gray-700 p-4 rounded-lg text-gray-300">
                  <pre className="whitespace-pre-wrap font-sans">{educationalContent.mindMapOutline}</pre>
                  <TextToSpeechButton textToSpeak={educationalContent.mindMapOutline} />
              </div>
            </section>
          )}

          {educationalContent.revisionNotes && (
            <section>
              <h3 className="text-2xl font-bold mb-3 text-gray-200">⚡ Quick Revision Notes</h3>
              <div className="bg-gray-700 p-4 rounded-lg text-gray-300">
                  <pre className="whitespace-pre-wrap font-sans">{educationalContent.revisionNotes}</pre>
                  <TextToSpeechButton textToSpeak={educationalContent.revisionNotes} />
              </div>
            </section>
          )}

          {educationalContent.formulaExplanations?.length > 0 && (
            <section>
              <h3 className="text-2xl font-bold mb-3 text-gray-200">🔬 Formula Explanations</h3>
              <div className="space-y-3">
                {educationalContent.formulaExplanations.map((item, index) => (
                  <div key={index} className="bg-gray-700 p-4 rounded-lg">
                      <p className="font-mono text-indigo-300 text-lg mb-2">{item.formula}</p>
                      <p className="text-gray-300 whitespace-pre-wrap">{item.explanation}</p>
                  </div>
                ))}
              </div>
            </section>
          )}

          {educationalContent.flashcards?.length > 0 && (
              <section>
                  <h3 className="text-2xl font-bold mb-3 text-gray-200">🃏 Flashcards</h3>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      {educationalContent.flashcards.map((card, index) => (
                          <Flashcard key={`flashcard-${index}`} flashcard={card} />
                      ))}
                  </div>
              </section>
          )}

          <section>
            <h3 className="text-2xl font-bold mb-3 text-gray-200">📝 Short Answer Questions</h3>
            <div className="space-y-3">
              {educationalContent.shortAnswerQuestions.map((pair, index) => (
                <QuestionAccordion key={`short-${index}`} qaPair={pair} />
              ))}
            </div>
          </section>

          <section>
            <h3 className="text-2xl font-bold mb-3 text-gray-200">📖 Long Answer Questions</h3>
            <div className="space-y-3">
              {educationalContent.longAnswerQuestions.map((pair, index) => (
                <QuestionAccordion key={`long-${index}`} qaPair={pair} />
              ))}
            </div>
          </section>

          <section>
            <h3 className="text-2xl font-bold mb-3 text-gray-200">🧠 Multiple Choice Questions</h3>
            <div className="space-y-3">
              {educationalContent.multipleChoiceQuestions.map((mcq, index) => (
                <MCQItem key={`mcq-${index}`} mcq={mcq} />
              ))}
            </div>
             <button
                onClick={startQuiz}
                className="mt-6 w-full bg-green-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-green-700 transition-colors duration-300"
              >
                Start Timed Quiz
              </button>
          </section>
        </div>
      );
    }

    return null;
  }

  return (
    <>
    {showProgressView && <ProgressView progressData={progressData} onClose={() => setShowProgressView(false)} onClearHistory={handleClearHistory} />}
    <div className="min-h-screen bg-gray-900 text-gray-100 flex flex-col items-center p-4 sm:p-6 lg:p-8">
      <div className="w-full max-w-4xl mx-auto">
        <header className="text-center mb-6">
            <div className="flex justify-center items-center gap-4">
              <h1 className="text-4xl sm:text-5xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-indigo-600">
                AI Study Buddy
              </h1>
              <button onClick={() => setShowProgressView(true)} className="text-gray-400 hover:text-white" aria-label="Track Progress">
                <ChartBarIcon className="w-8 h-8"/>
              </button>
            </div>
          <p className="mt-2 text-lg text-gray-400">
            Upload a page of notes, and let AI create a study guide for you.
          </p>
        </header>

        <main className="bg-gray-800 rounded-2xl shadow-2xl p-6">
          {!imageUrl ? (
            <div 
              className="w-full h-64 border-4 border-dashed border-gray-600 rounded-xl flex flex-col justify-center items-center text-center cursor-pointer hover:border-indigo-500 transition-colors duration-300"
              onClick={() => fileInputRef.current?.click()}
              onDrop={handleDrop}
              onDragOver={handleDragOver}
              onDragEnter={handleDragEnter}
              onDragLeave={handleDragLeave}
            >
              <CameraIcon className="w-16 h-16 text-gray-500 mb-4" />
              <h2 className="text-xl font-semibold text-gray-300">Upload an Image</h2>
              <p className="text-gray-400">Click to browse or drag & drop an image here</p>
              <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileChange}
                accept="image/*"
                className="hidden"
              />
            </div>
          ) : (
            <div className="flex flex-col lg:flex-row gap-6">
              <div className="lg:w-1/2 flex-shrink-0">
                <div className="relative group">
                  <img src={imageUrl} alt="Uploaded page" className="w-full h-auto object-contain rounded-lg shadow-lg max-h-[60vh]" />
                  <button onClick={handleReset} className="absolute top-2 right-2 p-2 bg-black bg-opacity-50 rounded-full text-white hover:bg-opacity-75 transition-all opacity-0 group-hover:opacity-100 focus:opacity-100">
                    <XCircleIcon className="w-6 h-6" />
                  </button>
                </div>

                <div className="mt-4">
                    <label className="block text-sm font-medium text-gray-300 mb-2">Select Difficulty</label>
                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                        {difficultyLevels.map((level) => (
                            <button key={level} onClick={() => setDifficulty(level)} className={`px-4 py-2 text-sm font-semibold rounded-md transition-colors duration-200 ${difficulty === level ? 'bg-indigo-600 text-white' : 'bg-gray-700 hover:bg-gray-600'}`}>
                                {level}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="mt-4 flex flex-col sm:flex-row gap-2">
                    <button
                        onClick={handleSubmit}
                        disabled={loadingState === 'processing'}
                        className="w-full bg-indigo-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-colors duration-300 disabled:bg-gray-500 disabled:cursor-not-allowed"
                    >
                        <SparklesIcon className="w-6 h-6" />
                        {loadingState === 'processing' ? 'Generating...' : 'Generate Study Guide'}
                    </button>
                    {loadingState === 'success' && (
                        <button
                            onClick={handleExportPdf}
                            disabled={isExportingPdf}
                            className="w-full sm:w-auto bg-gray-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-gray-700 transition-colors duration-300 disabled:bg-gray-500 disabled:cursor-not-allowed"
                        >
                            <DocumentArrowDownIcon className="w-6 h-6"/>
                            {isExportingPdf ? 'Exporting...' : 'Export PDF'}
                        </button>
                    )}
                </div>

              </div>
              <div className="lg:w-1/2 flex flex-col">
                {renderContent()}
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
    </>
  );
};

export default App;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { EducationalContent, Difficulty, QuizResult, ProgressRecord } from './types';
import { generateEducationalContentFromImage } from './services/geminiService';
import QuestionAccordion from './components/QuestionAccordion';
import MCQItem from './components/MCQItem';
import Flashcard from './components/Flashcard';
import QuizView from './components/QuizView';
import QuizResultsView from './components/QuizResultsView';
import TextToSpeechButton from './components/TextToSpeechButton';
import ProgressView from './components/ProgressView';
import { CameraIcon, SparklesIcon, XCircleIcon, DocumentArrowDownIcon, ChartBarIcon } from './components/icons';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';


type LoadingState = 'idle' | 'processing' | 'success' | 'error';
const difficultyLevels: Difficulty[] = ['Easy', 'Medium', 'Hard', 'Competitive Exam'];
const PROGRESS_STORAGE_KEY = 'ai-study-buddy-progress';

const App: React.FC = () => {
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [educationalContent, setEducationalContent] = useState<EducationalContent | null>(null);
  const [loadingState, setLoadingState] = useState<LoadingState>('idle');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [difficulty, setDifficulty] = useState<Difficulty>('Medium');
  const [isQuizActive, setIsQuizActive] = useState(false);
  const [quizResult, setQuizResult] = useState<QuizResult | null>(null);
  const [isExportingPdf, setIsExportingPdf] = useState(false);
  const [showProgressView, setShowProgressView] = useState(false);
  const [progressData, setProgressData] = useState<ProgressRecord[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    try {
        const storedProgress = localStorage.getItem(PROGRESS_STORAGE_KEY);
        if (storedProgress) {
            setProgressData(JSON.parse(storedProgress));
        }
    } catch (error) {
        console.error("Failed to load progress data:", error);
        setProgressData([]);
    }
  }, []);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      processFile(file);
    }
  };

  const processFile = (file: File) => {
    setImageFile(file);
    const reader = new FileReader();
    reader.onload = (e) => {
      setImageUrl(e.target?.result as string);
      setEducationalContent(null);
      setLoadingState('idle');
      setErrorMessage(null);
      setIsQuizActive(false);
      setQuizResult(null);
    };
    reader.readAsDataURL(file);
  };

  const handleDrop = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.remove('border-indigo-500');
    const file = event.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) {
        processFile(file);
    }
  };

  const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
  };

  const handleDragEnter = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.add('border-indigo-500');
  };

  const handleDragLeave = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.remove('border-indigo-500');
  };

  const handleSubmit = useCallback(async () => {
    if (!imageUrl) return;

    setLoadingState('processing');
    setErrorMessage(null);
    setEducationalContent(null);
    setIsQuizActive(false);
    setQuizResult(null);

    try {
      const base64Data = imageUrl.split(',')[1];
      const result = await generateEducationalContentFromImage(base64Data, imageFile?.type || 'image/jpeg', difficulty);
      setEducationalContent(result);
      setLoadingState('success');
    } catch (error) {
      console.error(error);
      setErrorMessage(error instanceof Error ? error.message : 'An unknown error occurred.');
      setLoadingState('error');
    }
  }, [imageUrl, imageFile, difficulty]);

  const handleReset = () => {
    setImageFile(null);
    setImageUrl(null);
    setEducationalContent(null);
    setLoadingState('idle');
    setErrorMessage(null);
    setDifficulty('Medium');
    setIsQuizActive(false);
    setQuizResult(null);
    if(fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleQuizComplete = (answers: (string | null)[]) => {
    if (!educationalContent) return;
    const score = answers.reduce((acc, answer, index) => {
      if (answer === educationalContent.multipleChoiceQuestions[index].correctAnswer) {
        return acc + 1;
      }
      return acc;
    }, 0);
    setQuizResult({ score, answers });
    setIsQuizActive(false);

    // Save progress
    const newRecord: ProgressRecord = {
        topic: educationalContent.topicSummary.substring(0, 50) + '...', // Truncate for display
        score,
        total: educationalContent.multipleChoiceQuestions.length,
        date: new Date().toISOString(),
    };
    const updatedProgress = [newRecord, ...progressData];
    setProgressData(updatedProgress);
    localStorage.setItem(PROGRESS_STORAGE_KEY, JSON.stringify(updatedProgress));
  };

  const startQuiz = () => {
    setQuizResult(null);
    setIsQuizActive(true);
  };

  const handleExportPdf = async () => {
    if (!contentRef.current) return;
    setIsExportingPdf(true);
    try {
