                  <TextToSpeechButton textToSpeak={educationalContent.revisionNotes} />
              </div>
            </section>
          )}

          {educationalContent.formulaExplanations?.length > 0 && (
            <section>
              <h3 className="text-2xl font-bold mb-3 text-gray-200">🔬 Formula Explanations</h3>
              <div className="space-y-3">
                {educationalContent.formulaExplanations.map((item, index) => (
                  <div key={index} className="bg-gray-700 p-4 rounded-lg">
                      <p className="font-mono text-indigo-300 text-lg mb-2">{item.formula}</p>
                      <p className="text-gray-300 whitespace-pre-wrap">{item.explanation}</p>
                      <TextToSpeechButton textToSpeak={`Formula: ${item.formula}. Explanation: ${item.explanation}`} />
                  </div>
                ))}
