export async function generateEducationalContentFromImage(base64ImageData: string, mimeType: string, difficulty: Difficulty): Promise<EducationalContent> {
    const imagePart = {
        inlineData: {
            data: base64ImageData,
            mimeType: mimeType,
        },
    };

    const difficultyInstructions = getDifficultyInstructions(difficulty);

    const textPart = {
        text: `You are an advanced educational AI. Your first and most important task is to carefully analyze the provided image of a textbook page or notes and extract the text.

        **Image Analysis Rules:**
        - If parts of the text are unclear or obscured, try to logically reconstruct incomplete words based on context.
        - Ignore any irrelevant marks, scribbles, or artifacts on the page.
        - It is crucial that you do not invent or hallucinate any content that is not present in the image.
        - If the text is completely unreadable and you cannot extract any meaningful content, you must still adhere to the JSON output format. For the 'topicSummary', you must provide a polite message explaining the issue (e.g., "The text in the image is too blurry to read. Please upload a clearer picture."). For all question/flashcard arrays, you must still provide the required number of items, but they can be placeholders acknowledging the unreadable text.

        **Study Guide Generation:**
        Once you have analyzed the text, perform the following tasks:

        **CRITICAL LANGUAGE INSTRUCTION:** First, identify the primary language of the text you have extracted. All of the following generated content (summaries, questions, answers, notes, etc.) **MUST** be in that same identified language. For example, if the text is in Hindi, the entire study guide must be in Hindi.

        1. Summarize the main topic in a concise paragraph.
        2. Convert the topic into a structured mind map outline using a nested bullet point hierarchy.
        3. Create a 'Quick Revision Notes' section. This should be a concise, one-page summary highlighting only the most critical key points, definitions, and formulas from the text. Use bullet points for clarity.
        4. Generate exactly 10 flashcards (simple question/answer pairs) covering the key concepts.
        5. Generate exactly 5 short answer questions based on the text.
        6. Generate exactly 5 long answer questions that require more detailed explanation.
        7. Generate exactly 5 multiple choice questions, each with 4 distinct options.
        8. Provide clear, student-friendly answers for all questions.
        9. If the page contains any mathematical or scientific formulas, identify them and explain each one step-by-step. If there are no formulas, this section must be an empty array.

        ${difficultyInstructions}

        Provide the output in a structured JSON format according to the provided schema.`,
    };

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: [imagePart, textPart] },
            config: {
                responseMimeType: "application/json",
                responseSchema: educationalContentSchema,
            },
        });

        const jsonText = response.text;
        if (!jsonText) {
            throw new Error("API returned an empty response.");
        }

        const parsedJson = JSON.parse(jsonText);
        return parsedJson as EducationalContent;

    } catch (error) {
        console.error("Error calling Gemini API:", error);
        throw new Error("Failed to generate educational content from the image. Please check the console for details.");
    }
}


export async function generateSpeech(text: string): Promise<string> {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' },
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

        if (!base64Audio) {
            throw new Error("No audio data returned from the API.");
        }

        return base64Audio;
    } catch (error) {
        console.error("Error generating speech:", error);
        throw new Error("Failed to generate speech. Please check the console for details.");
    }
}

export async function translateText(text: string, targetLanguage: string): Promise<string> {
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Translate the following text to ${targetLanguage}. Do not add any extra commentary, introductory phrases, or explanations. Only provide the direct translation of the text itself.\n\nText: "${text}"`,
        });

        const translatedText = response.text;
        if (!translatedText) {
            throw new Error("API returned an empty response for translation.");
        }
        return translatedText.trim();
    } catch (error) {
        console.error(`Error translating text to ${targetLanguage}:`, error);
        throw new Error(`Failed to translate text. Please try again.`);
    }
}

