import React from 'react';
import { ProgressRecord } from '../types';
import { XCircleIcon, ClockIcon } from './icons';

interface ProgressViewProps {
  progressData: ProgressRecord[];
  onClose: () => void;
  onClearHistory: () => void;
}

const ProgressView: React.FC<ProgressViewProps> = ({ progressData, onClose, onClearHistory }) => {
  return (
    <div className="fixed inset-0 bg-black bg-opacity-70 flex justify-center items-center z-50 p-4 animate-fade-in">
      <div className="bg-gray-800 rounded-2xl shadow-2xl p-6 w-full max-w-2xl max-h-[90vh] flex flex-col">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-2xl font-bold text-indigo-300">Quiz Progress History</h2>
          <button onClick={onClose} className="text-gray-400 hover:text-white">
            <XCircleIcon className="w-8 h-8" />
          </button>
        </div>
        {progressData.length > 0 ? (
          <>
            <div className="overflow-y-auto flex-grow pr-2 space-y-3">
              {progressData.map((record, index) => (
                <div key={index} className="bg-gray-700 p-4 rounded-lg flex justify-between items-center">
                  <div>
                    <p className="font-semibold text-gray-200 truncate">{record.topic}</p>
                    <div className="flex items-center gap-2 text-sm text-gray-400 mt-1">
                       <ClockIcon className="w-4 h-4" />
                       <span>{new Date(record.date).toLocaleString()}</span>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-xl font-bold text-white">
                      {record.score} / {record.total}
                    </p>
                    <p className="text-sm text-indigo-400">
                      ({((record.score / record.total) * 100).toFixed(0)}%)
                    </p>
                  </div>
                </div>
              ))}
            </div>
            <div className="mt-4 text-right">
                <button onClick={onClearHistory} className="text-sm text-red-400 hover:text-red-300">Clear History</button>
            </div>
          </>
        ) : (
          <div className="text-center py-10">
            <p className="text-gray-400">No quiz history yet. Complete a quiz to see your progress!</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProgressView;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { EducationalContent, StudyMode, QuizResult, ProgressRecord } from './types';
import { generateEducationalContentFromImage, generateEducationalContentFromText } from './services/geminiService';
import QuestionAccordion from './components/QuestionAccordion';
import MCQItem from './components/MCQItem';
import Flashcard from './components/Flashcard';
import QuizView from './components/QuizView';
import QuizResultsView from './components/QuizResultsView';
import TextToSpeechButton from './components/TextToSpeechButton';
import ProgressView from './components/ProgressView';
import { CameraIcon, SparklesIcon, XCircleIcon, DocumentArrowDownIcon, MicrophoneIcon, BookOpenIcon, MapIcon, BoltIcon, CalculatorIcon, RectangleStackIcon, PencilIcon, ChatBubbleLeftRightIcon, PuzzlePieceIcon, ChevronDownIcon, ChartBarIcon } from './components/icons';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';


type LoadingState = 'idle' | 'processing' | 'success' | 'error';
type InputMethod = 'image' | 'text';

const studyModes: { id: StudyMode, name: string, description: string }[] = [
    { id: 'Student', name: 'Student Mode', description: 'For classes 6-12 homework help with step-by-step explanations.' },
    { id: 'Exam', name: 'Exam Prep Mode', description: 'For JEE, NEET & Boards with challenging questions.' },
];
const PROGRESS_STORAGE_KEY = 'ai-study-buddy-progress';

// SpeechRecognition setup
const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
let recognition: any;
if (SpeechRecognition) {
    recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.lang = 'en-US';
    recognition.interimResults = false;
}

const StudyGuideSection: React.FC<{ title: string; icon: React.ReactNode; children: React.ReactNode; defaultOpen?: boolean }> = ({ title, icon, children, defaultOpen = false }) => (
    <details className="bg-gray-700 rounded-lg overflow-hidden transition-all duration-300 group" open={defaultOpen}>
        <summary className="p-4 flex justify-between items-center cursor-pointer list-none hover:bg-gray-600">
            <div className="flex items-center gap-3">
                <span className="text-indigo-400">{icon}</span>
                <h3 className="text-xl font-bold text-gray-200">{title}</h3>
            </div>
            <ChevronDownIcon className="w-5 h-5 text-gray-400 transition-transform duration-300 group-open:rotate-180" />
        </summary>
        <div className="p-4 border-t border-gray-600 bg-gray-800">
            {children}
        </div>
    </details>
);

const App: React.FC = () => {
  const [inputMethod, setInputMethod] = useState<InputMethod>('image');
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [textInput, setTextInput] = useState('');
  const [isListening, setIsListening] = useState(false);

  const [educationalContent, setEducationalContent] = useState<EducationalContent | null>(null);
  const [loadingState, setLoadingState] = useState<LoadingState>('idle');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [studyMode, setStudyMode] = useState<StudyMode>('Student');

  const [isQuizActive, setIsQuizActive] = useState(false);
  const [quizResult, setQuizResult] = useState<QuizResult | null>(null);
  const [isExportingPdf, setIsExportingPdf] = useState(false);
  const [showProgressView, setShowProgressView] = useState(false);
  const [progressData, setProgressData] = useState<ProgressRecord[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    try {
        const storedProgress = localStorage.getItem(PROGRESS_STORAGE_KEY);
        if (storedProgress) { setProgressData(JSON.parse(storedProgress)); }
    } catch (error) {
        console.error("Failed to load progress data:", error);
        setProgressData([]);
    }
  }, []);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) { processFile(file); }
  };

  const processFile = (file: File) => {
    setImageFile(file);
    const reader = new FileReader();
    reader.onload = (e) => {
      setImageUrl(e.target?.result as string);
      resetContentState();
    };
    reader.readAsDataURL(file);
  };

  const handleDrop = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.remove('border-indigo-500');
    const file = event.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) { processFile(file); }
  };

  const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => event.preventDefault();
  const handleDragEnter = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.currentTarget.classList.add('border-indigo-500');
  };
  const handleDragLeave = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.currentTarget.classList.remove('border-indigo-500');
  };

  const handleSubmit = useCallback(async () => {
    if ((inputMethod === 'image' && !imageUrl) || (inputMethod === 'text' && !textInput.trim())) return;

    setLoadingState('processing');
    setErrorMessage(null);
    setEducationalContent(null);
    setIsQuizActive(false);
    setQuizResult(null);

    try {
      let result: EducationalContent;
      if (inputMethod === 'image' && imageUrl) {
        const base64Data = imageUrl.split(',')[1];
        result = await generateEducationalContentFromImage(base64Data, imageFile?.type || 'image/jpeg', studyMode);
      } else if (inputMethod === 'text' && textInput.trim()) {
        result = await generateEducationalContentFromText(textInput, studyMode);
      } else {
        throw new Error("Invalid input for generation.");
      }
      setEducationalContent(result);
      setLoadingState('success');
    } catch (error) {
      console.error(error);
      setErrorMessage(error instanceof Error ? error.message : 'An unknown error occurred.');
      setLoadingState('error');
    }
  }, [imageUrl, imageFile, studyMode, textInput, inputMethod]);

  const resetContentState = () => {
    setEducationalContent(null);
    setLoadingState('idle');
    setErrorMessage(null);
    setIsQuizActive(false);
    setQuizResult(null);
  };

  const handleReset = () => {
    setImageFile(null);
    setImageUrl(null);
    setTextInput('');
    resetContentState();
    if(fileInputRef.current) { fileInputRef.current.value = ""; }
  };

  const handleVoiceInput = () => {
    if (!recognition || isListening) return;

    recognition.start();
    setIsListening(true);

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setTextInput(transcript);
    };

    recognition.onerror = (event: any) => {
      console.error('Speech recognition error:', event.error);
      setIsListening(false);
    };

    recognition.onend = () => {
      setIsListening(false);
    };
  };

  const handleQuizComplete = (answers: (string | null)[]) => {
    if (!educationalContent) return;
    const score = answers.reduce((acc, answer, index) => {
      if (answer === educationalContent.multipleChoiceQuestions[index].correctAnswer) {
        return acc + 1;
      }
      return acc;
    }, 0);
    setQuizResult({ score, answers });
    setIsQuizActive(false);

    const newRecord: ProgressRecord = {
        topic: educationalContent.topicSummary.substring(0, 50) + '...',
        score,
        total: educationalContent.multipleChoiceQuestions.length,
        date: new Date().toISOString(),
    };
    const updatedProgress = [newRecord, ...progressData];
    setProgressData(updatedProgress);
    localStorage.setItem(PROGRESS_STORAGE_KEY, JSON.stringify(updatedProgress));
  };

  const startQuiz = () => {
    setQuizResult(null);
    setIsQuizActive(true);
  };

  const handleExportPdf = async () => {
    if (!contentRef.current) return;
    setIsExportingPdf(true);
    try {
        const canvas = await html2canvas(contentRef.current, { scale: 2, backgroundColor: '#1f2937' });
        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF({ orientation: 'p', unit: 'px', format: [canvas.width, canvas.height] });
        pdf.addImage(imgData, 'PNG', 0, 0, canvas.width, canvas.height);
        pdf.save('ai-study-buddy-guide.pdf');
    } catch (error) {
        console.error("Failed to export PDF:", error);
    } finally {
        setIsExportingPdf(false);
    }
  };

  const handleClearHistory = () => {
    setProgressData([]);
    localStorage.removeItem(PROGRESS_STORAGE_KEY);
  };

  const renderInitialView = () => (
    <div className="space-y-4">
      {inputMethod === 'image' ? (
        <>
            <div 
              className="w-full h-64 border-4 border-dashed border-gray-600 rounded-xl flex flex-col justify-center items-center text-center cursor-pointer hover:border-indigo-500 transition-colors duration-300"
              onClick={() => fileInputRef.current?.click()}
              onDrop={handleDrop} onDragOver={handleDragOver} onDragEnter={handleDragEnter} onDragLeave={handleDragLeave}
            >
              <CameraIcon className="w-16 h-16 text-gray-500 mb-4" />
              <h2 className="text-xl font-semibold text-gray-300">Upload an Image</h2>
              <p className="text-gray-400">Click to browse or drag & drop here</p>
              <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
            </div>
            <p className="text-center text-sm text-gray-400">
                Or <button onClick={() => setInputMethod('text')} className="text-indigo-400 hover:underline">Use Voice or Text Input</button>
            </p>
        </>
      ) : (
        <>
            <div className="relative">
                <textarea
                    value={textInput}
                    onChange={(e) => {
                        setTextInput(e.target.value);
                        if(e.target.value) resetContentState();
                    }}
                    placeholder="Type or paste your text here, or use the microphone to speak..."
                    className="w-full h-64 p-4 bg-gray-900 border-2 border-gray-600 rounded-xl resize-none focus:border-indigo-500 focus:ring-0"
                />
                <button
                    onClick={handleVoiceInput}
                    disabled={!SpeechRecognition || isListening}
                    className={`absolute bottom-4 right-4 p-3 rounded-full transition-colors ${isListening ? 'bg-red-500 animate-pulse' : 'bg-indigo-600 hover:bg-indigo-700'} disabled:bg-gray-500 disabled:cursor-not-allowed`}
                    aria-label="Use voice input"
                >
                    <MicrophoneIcon className="w-6 h-6 text-white"/>
                </button>
            </div>
            <p className="text-center text-sm text-gray-400">
                Or <button onClick={() => setInputMethod('image')} className="text-indigo-400 hover:underline">Upload an Image</button>
            </p>
        </>
      )}
    </div>
  );

  const renderContent = () => {
    if (isQuizActive && educationalContent?.multipleChoiceQuestions) {
        return <QuizView mcqs={educationalContent.multipleChoiceQuestions} onQuizComplete={handleQuizComplete} />;
    }
    if (quizResult && educationalContent?.multipleChoiceQuestions) {
        return <QuizResultsView mcqs={educationalContent.multipleChoiceQuestions} result={quizResult} onRetake={startQuiz} onBackToStudyGuide={() => setQuizResult(null)} />;
    }
    if (loadingState === 'processing') {
      return <div className="flex flex-col items-center justify-center h-full text-center"><div className="w-12 h-12 border-4 border-t-indigo-500 border-gray-600 rounded-full animate-spin mb-4"></div><p className="text-lg font-semibold text-gray-300">Creating your study guide...</p><p className="text-gray-400">This might take a moment.</p></div>;
    }
    if (loadingState === 'error') {
      return <div className="flex items-center justify-center h-full text-center bg-red-900 bg-opacity-30 p-4 rounded-lg"><div><XCircleIcon className="w-12 h-12 text-red-400 mx-auto mb-2" /><p className="text-red-400 font-semibold">An error occurred</p><p className="text-red-300 text-sm">{errorMessage}</p></div></div>;
    }
    if (loadingState === 'success' && educationalContent) {
      return (
        <div ref={contentRef} className="space-y-4 overflow-y-auto max-h-[80vh] p-1">
            <StudyGuideSection title="Topic Summary" icon={<BookOpenIcon className="w-6 h-6" />} defaultOpen>
                <p className="whitespace-pre-wrap text-gray-300">{educationalContent.topicSummary}</p>
                <TextToSpeechButton textToSpeak={educationalContent.topicSummary} />
            </StudyGuideSection>

            {educationalContent.mindMapOutline && (
                <StudyGuideSection title="Mind Map Outline" icon={<MapIcon className="w-6 h-6" />}>
                    <pre className="whitespace-pre-wrap font-sans text-gray-300">{educationalContent.mindMapOutline}</pre>
                    <TextToSpeechButton textToSpeak={educationalContent.mindMapOutline} />
                </StudyGuideSection>
            )}

            {educationalContent.revisionNotes && (
                <StudyGuideSection title="Quick Revision Notes" icon={<BoltIcon className="w-6 h-6" />}>
                     <pre className="whitespace-pre-wrap font-sans text-gray-300">{educationalContent.revisionNotes}</pre>
                    <TextToSpeechButton textToSpeak={educationalContent.revisionNotes} />
                </StudyGuideSection>
            )}

            {educationalContent.formulaExplanations?.length > 0 && (
                <StudyGuideSection title="Formula & Problem Solvers" icon={<CalculatorIcon className="w-6 h-6" />}>
                    <div className="space-y-3">{educationalContent.formulaExplanations.map((item, index) => (
                        <div key={index} className="bg-gray-700 p-4 rounded-lg">
                            <p className="font-mono text-indigo-300 text-lg mb-2">{item.formula}</p>
                            <p className="text-gray-300 whitespace-pre-wrap">{item.explanation}</p>
                            <TextToSpeechButton textToSpeak={`Formula: ${item.formula}. Explanation: ${item.explanation}`} />
                        </div>
                    ))}</div>
                </StudyGuideSection>
            )}

            {educationalContent.flashcards?.length > 0 && (
                <StudyGuideSection title="Flashcards" icon={<RectangleStackIcon className="w-6 h-6" />}>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        {educationalContent.flashcards.map((card, index) => <Flashcard key={`flashcard-${index}`} flashcard={card} />)}
                    </div>
                </StudyGuideSection>
            )}

            {educationalContent.shortAnswerQuestions?.length > 0 && (
                <StudyGuideSection title="Short Answer Questions" icon={<PencilIcon className="w-6 h-6" />}>
                    <div className="space-y-3">
                        {educationalContent.shortAnswerQuestions.map((pair, index) => <QuestionAccordion key={`short-${index}`} qaPair={pair} />)}
                    </div>
                </StudyGuideSection>
            )}

            {educationalContent.longAnswerQuestions?.length > 0 && (
                <StudyGuideSection title="Long Answer Questions" icon={<ChatBubbleLeftRightIcon className="w-6 h-6" />}>
                    <div className="space-y-3">
                        {educationalContent.longAnswerQuestions.map((pair, index) => <QuestionAccordion key={`long-${index}`} qaPair={pair} />)}
                    </div>
                </StudyGuideSection>
            )}

            {educationalContent.multipleChoiceQuestions?.length > 0 && (
                <StudyGuideSection title="Multiple Choice Questions" icon={<PuzzlePieceIcon className="w-6 h-6" />}>
                     <div className="space-y-3">
                        {educationalContent.multipleChoiceQuestions.map((mcq, index) => <MCQItem key={`mcq-${index}`} mcq={mcq} />)}
                    </div>
                    <button onClick={startQuiz} className="mt-6 w-full bg-green-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-green-700 transition-colors duration-300">Start Timed Quiz</button>
                </StudyGuideSection>
            )}
        </div>
      );
    }
    return null;
  }

  const hasInput = (inputMethod === 'image' && imageUrl) || (inputMethod === 'text' && textInput);

  return (
    <>
    {showProgressView && <ProgressView progressData={progressData} onClose={() => setShowProgressView(false)} onClearHistory={handleClearHistory} />}
    <div className="min-h-screen bg-gray-900 text-gray-100 flex flex-col items-center p-4 sm:p-6 lg:p-8">
      <div className="w-full max-w-4xl mx-auto">
        <header className="text-center mb-6">
            <div className="flex justify-center items-center gap-4"><h1 className="text-4xl sm:text-5xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-indigo-600">AI Study Buddy</h1><button onClick={() => setShowProgressView(true)} className="text-gray-400 hover:text-white" aria-label="Track Progress"><ChartBarIcon className="w-8 h-8"/></button></div>
            <p className="mt-2 text-lg text-gray-400">Your personal AI-powered tutor for homework and exam prep.</p>
        </header>

        <main className="bg-gray-800 rounded-2xl shadow-2xl p-6">
          {!hasInput ? renderInitialView() : (
            <div className="flex flex-col lg:flex-row gap-6">
              <div className="lg:w-1/2 flex-shrink-0">
                <div className="relative group">
                  {imageUrl && inputMethod === 'image' ? <img src={imageUrl} alt="Uploaded page" className="w-full h-auto object-contain rounded-lg shadow-lg max-h-[60vh]" /> : <div className="bg-gray-900 p-4 rounded-lg max-h-[60vh] overflow-y-auto"><p className="text-gray-300 whitespace-pre-wrap">{textInput}</p></div> }
                  <button onClick={handleReset} className="absolute top-2 right-2 p-2 bg-black bg-opacity-50 rounded-full text-white hover:bg-opacity-75 transition-all opacity-0 group-hover:opacity-100 focus:opacity-100"><XCircleIcon className="w-6 h-6" /></button>
                </div>

                <div className="mt-4">
                    <label className="block text-sm font-medium text-gray-300 mb-2">Select Study Mode</label>
                    <div className="grid grid-cols-2 gap-2">
                        {studyModes.map((mode) => (
                            <button key={mode.id} onClick={() => setStudyMode(mode.id)} className={`p-3 text-sm font-semibold rounded-md transition-colors duration-200 text-left ${studyMode === mode.id ? 'bg-indigo-600 text-white ring-2 ring-indigo-400' : 'bg-gray-700 hover:bg-gray-600'}`}>
                                <span className="block font-bold">{mode.name}</span>
                                <span className="block text-xs opacity-80">{mode.description}</span>
                            </button>
                        ))}
                    </div>
                </div>

                <div className="mt-4 flex flex-col sm:flex-row gap-2">
                    <button onClick={handleSubmit} disabled={loadingState === 'processing'} className="w-full bg-indigo-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-colors duration-300 disabled:bg-gray-500 disabled:cursor-not-allowed"><SparklesIcon className="w-6 h-6" />{loadingState === 'processing' ? 'Generating...' : 'Generate Study Guide'}</button>
                    {loadingState === 'success' && (<button onClick={handleExportPdf} disabled={isExportingPdf} className="w-full sm:w-auto bg-gray-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-gray-700 transition-colors duration-300 disabled:bg-gray-500 disabled:cursor-not-allowed"><DocumentArrowDownIcon className="w-6 h-6"/>{isExportingPdf ? 'Exporting...' : 'Export PDF'}</button>)}
                </div>
              </div>

              <div className="lg:w-1/2 flex flex-col">{renderContent()}</div>
            </div>
          )}
        </main>
      </div>
    </div>
    </>
  );
};

export default App;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { EducationalContent, StudyMode, QuizResult } from './types';
import { generateEducationalContentFromImage, generateEducationalContentFromText } from './services/geminiService';
import QuestionAccordion from './components/QuestionAccordion';
import MCQItem from './components/MCQItem';
import Flashcard from './components/Flashcard';
import QuizView from './components/QuizView';
import QuizResultsView from './components/QuizResultsView';
import TextToSpeechButton from './components/TextToSpeechButton';
import { CameraIcon, SparklesIcon, XCircleIcon, DocumentArrowDownIcon, MicrophoneIcon, BookOpenIcon, MapIcon, BoltIcon, CalculatorIcon, RectangleStackIcon, PencilIcon, ChatBubbleLeftRightIcon, PuzzlePieceIcon, ChevronDownIcon } from './components/icons';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';


type LoadingState = 'idle' | 'processing' | 'success' | 'error';
type InputMethod = 'image' | 'text';

const studyModes: { id: StudyMode, name: string, description: string }[] = [
    { id: 'Student', name: 'Student Mode', description: 'For classes 6-12 homework help with step-by-step explanations.' },
    { id: 'Exam', name: 'Exam Prep Mode', description: 'For JEE, NEET & Boards with challenging questions.' },
];

// SpeechRecognition setup
const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
let recognition: any;
if (SpeechRecognition) {
    recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.lang = 'en-US';
    recognition.interimResults = false;
}

const StudyGuideSection: React.FC<{ title: string; icon: React.ReactNode; children: React.ReactNode; defaultOpen?: boolean }> = ({ title, icon, children, defaultOpen = false }) => (
    <details className="bg-gray-700 rounded-lg overflow-hidden transition-all duration-300 group" open={defaultOpen}>
        <summary className="p-4 flex justify-between items-center cursor-pointer list-none hover:bg-gray-600">
            <div className="flex items-center gap-3">
                <span className="text-indigo-400">{icon}</span>
                <h3 className="text-xl font-bold text-gray-200">{title}</h3>
            </div>
            <ChevronDownIcon className="w-5 h-5 text-gray-400 transition-transform duration-300 group-open:rotate-180" />
        </summary>
        <div className="p-4 border-t border-gray-600 bg-gray-800">
            {children}
        </div>
    </details>
);

const App: React.FC = () => {
  const [inputMethod, setInputMethod] = useState<InputMethod>('image');
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [textInput, setTextInput] = useState('');
  const [isListening, setIsListening] = useState(false);

  const [educationalContent, setEducationalContent] = useState<EducationalContent | null>(null);
  const [loadingState, setLoadingState] = useState<LoadingState>('idle');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [studyMode, setStudyMode] = useState<StudyMode>('Student');

  const [isQuizActive, setIsQuizActive] = useState(false);
  const [quizResult, setQuizResult] = useState<QuizResult | null>(null);
  const [isExportingPdf, setIsExportingPdf] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) { processFile(file); }
  };

  const processFile = (file: File) => {
    setImageFile(file);
    const reader = new FileReader();
    reader.onload = (e) => {
      setImageUrl(e.target?.result as string);
      resetContentState();
    };
    reader.readAsDataURL(file);
  };

  const handleDrop = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.remove('border-indigo-500');
    const file = event.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) { processFile(file); }
  };

  const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => event.preventDefault();
  const handleDragEnter = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.currentTarget.classList.add('border-indigo-500');
  };
  const handleDragLeave = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.currentTarget.classList.remove('border-indigo-500');
  };

  const handleSubmit = useCallback(async () => {
    if ((inputMethod === 'image' && !imageUrl) || (inputMethod === 'text' && !textInput.trim())) return;

    setLoadingState('processing');
    setErrorMessage(null);
    setEducationalContent(null);
    setIsQuizActive(false);
    setQuizResult(null);

    try {
      let result: EducationalContent;
      if (inputMethod === 'image' && imageUrl) {
        const base64Data = imageUrl.split(',')[1];
        result = await generateEducationalContentFromImage(base64Data, imageFile?.type || 'image/jpeg', studyMode);
      } else if (inputMethod === 'text' && textInput.trim()) {
        result = await generateEducationalContentFromText(textInput, studyMode);
      } else {
        throw new Error("Invalid input for generation.");
      }
      setEducationalContent(result);
      setLoadingState('success');
    } catch (error) {
      console.error(error);
      setErrorMessage(error instanceof Error ? error.message : 'An unknown error occurred.');
      setLoadingState('error');
    }
  }, [imageUrl, imageFile, studyMode, textInput, inputMethod]);

  const resetContentState = () => {
    setEducationalContent(null);
    setLoadingState('idle');
    setErrorMessage(null);
    setIsQuizActive(false);
    setQuizResult(null);
  };

  const handleReset = () => {
    setImageFile(null);
    setImageUrl(null);
    setTextInput('');
    resetContentState();
    if(fileInputRef.current) { fileInputRef.current.value = ""; }
  };

  const handleVoiceInput = () => {
    if (!recognition || isListening) return;

    recognition.start();
    setIsListening(true);

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setTextInput(transcript);
    };

    recognition.onerror = (event: any) => {
      console.error('Speech recognition error:', event.error);
      setIsListening(false);
    };

    recognition.onend = () => {
      setIsListening(false);
    };
  };

  const handleQuizComplete = (answers: (string | null)[]) => {
    if (!educationalContent) return;
    const score = answers.reduce((acc, answer, index) => {
      if (answer === educationalContent.multipleChoiceQuestions[index].correctAnswer) {
        return acc + 1;
      }
      return acc;
    }, 0);
    setQuizResult({ score, answers });
    setIsQuizActive(false);
  };

  const startQuiz = () => {
    setQuizResult(null);
    setIsQuizActive(true);
  };

  const handleExportPdf = async () => {
    if (!contentRef.current) return;
    setIsExportingPdf(true);
    try {
        const canvas = await html2canvas(contentRef.current, { scale: 2, backgroundColor: '#1f2937' });
        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF({ orientation: 'p', unit: 'px', format: [canvas.width, canvas.height] });
        pdf.addImage(imgData, 'PNG', 0, 0, canvas.width, canvas.height);
        pdf.save('ai-study-buddy-guide.pdf');
    } catch (error) {
        console.error("Failed to export PDF:", error);
    } finally {
        setIsExportingPdf(false);
    }
  };

  const renderInitialView = () => (
    <div className="space-y-4">
      {inputMethod === 'image' ? (
        <>
            <div 
              className="w-full h-64 border-4 border-dashed border-gray-600 rounded-xl flex flex-col justify-center items-center text-center cursor-pointer hover:border-indigo-500 transition-colors duration-300"
              onClick={() => fileInputRef.current?.click()}
              onDrop={handleDrop} onDragOver={handleDragOver} onDragEnter={handleDragEnter} onDragLeave={handleDragLeave}
            >
              <CameraIcon className="w-16 h-16 text-gray-500 mb-4" />
              <h2 className="text-xl font-semibold text-gray-300">Upload an Image</h2>
              <p className="text-gray-400">Click to browse or drag & drop here</p>
              <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
            </div>
            <p className="text-center text-sm text-gray-400">
                Or <button onClick={() => setInputMethod('text')} className="text-indigo-400 hover:underline">Use Voice or Text Input</button>
            </p>
        </>
      ) : (
        <>
            <div className="relative">
                <textarea
                    value={textInput}
                    onChange={(e) => {
                        setTextInput(e.target.value);
                        if(e.target.value) resetContentState();
                    }}
                    placeholder="Type or paste your text here, or use the microphone to speak..."
                    className="w-full h-64 p-4 bg-gray-900 border-2 border-gray-600 rounded-xl resize-none focus:border-indigo-500 focus:ring-0"
                />
                <button
                    onClick={handleVoiceInput}
                    disabled={!SpeechRecognition || isListening}
                    className={`absolute bottom-4 right-4 p-3 rounded-full transition-colors ${isListening ? 'bg-red-500 animate-pulse' : 'bg-indigo-600 hover:bg-indigo-700'} disabled:bg-gray-500 disabled:cursor-not-allowed`}
                    aria-label="Use voice input"
                >
                    <MicrophoneIcon className="w-6 h-6 text-white"/>
                </button>
            </div>
            <p className="text-center text-sm text-gray-400">
                Or <button onClick={() => setInputMethod('image')} className="text-indigo-400 hover:underline">Upload an Image</button>
            </p>
        </>
      )}
    </div>
  );

  const renderContent = () => {
    if (isQuizActive && educationalContent?.multipleChoiceQuestions) {
        return <QuizView mcqs={educationalContent.multipleChoiceQuestions} onQuizComplete={handleQuizComplete} />;
    }
    if (quizResult && educationalContent?.multipleChoiceQuestions) {
        return <QuizResultsView mcqs={educationalContent.multipleChoiceQuestions} result={quizResult} onRetake={startQuiz} onBackToStudyGuide={() => setQuizResult(null)} />;
    }
    if (loadingState === 'processing') {
      return <div className="flex flex-col items-center justify-center h-full text-center"><div className="w-12 h-12 border-4 border-t-indigo-500 border-gray-600 rounded-full animate-spin mb-4"></div><p className="text-lg font-semibold text-gray-300">Creating your study guide...</p><p className="text-gray-400">This might take a moment.</p></div>;
    }
    if (loadingState === 'error') {
      return <div className="flex items-center justify-center h-full text-center bg-red-900 bg-opacity-30 p-4 rounded-lg"><div><XCircleIcon className="w-12 h-12 text-red-400 mx-auto mb-2" /><p className="text-red-400 font-semibold">An error occurred</p><p className="text-red-300 text-sm">{errorMessage}</p></div></div>;
    }
    if (loadingState === 'success' && educationalContent) {
      return (
        <div ref={contentRef} className="space-y-4 overflow-y-auto max-h-[80vh] p-1">
            <StudyGuideSection title="Topic Summary" icon={<BookOpenIcon className="w-6 h-6" />} defaultOpen>
                <p className="whitespace-pre-wrap text-gray-300">{educationalContent.topicSummary}</p>
                <TextToSpeechButton textToSpeak={educationalContent.topicSummary} />
            </StudyGuideSection>

            {educationalContent.mindMapOutline && (
                <StudyGuideSection title="Mind Map Outline" icon={<MapIcon className="w-6 h-6" />}>
                    <pre className="whitespace-pre-wrap font-sans text-gray-300">{educationalContent.mindMapOutline}</pre>
                    <TextToSpeechButton textToSpeak={educationalContent.mindMapOutline} />
                </StudyGuideSection>
            )}

            {educationalContent.revisionNotes && (
                <StudyGuideSection title="Quick Revision Notes" icon={<BoltIcon className="w-6 h-6" />}>
                     <pre className="whitespace-pre-wrap font-sans text-gray-300">{educationalContent.revisionNotes}</pre>
                    <TextToSpeechButton textToSpeak={educationalContent.revisionNotes} />
                </StudyGuideSection>
            )}

            {educationalContent.formulaExplanations?.length > 0 && (
                <StudyGuideSection title="Formula & Problem Solvers" icon={<CalculatorIcon className="w-6 h-6" />}>
                    <div className="space-y-3">{educationalContent.formulaExplanations.map((item, index) => (
                        <div key={index} className="bg-gray-700 p-4 rounded-lg">
                            <p className="font-mono text-indigo-300 text-lg mb-2">{item.formula}</p>
                            <p className="text-gray-300 whitespace-pre-wrap">{item.explanation}</p>
                            <TextToSpeechButton textToSpeak={`Formula: ${item.formula}. Explanation: ${item.explanation}`} />
                        </div>
                    ))}</div>
                </StudyGuideSection>
            )}

            {educationalContent.flashcards?.length > 0 && (
                <StudyGuideSection title="Flashcards" icon={<RectangleStackIcon className="w-6 h-6" />}>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        {educationalContent.flashcards.map((card, index) => <Flashcard key={`flashcard-${index}`} flashcard={card} />)}
                    </div>
                </StudyGuideSection>
            )}

            {educationalContent.shortAnswerQuestions?.length > 0 && (
                <StudyGuideSection title="Short Answer Questions" icon={<PencilIcon className="w-6 h-6" />}>
                    <div className="space-y-3">
                        {educationalContent.shortAnswerQuestions.map((pair, index) => <QuestionAccordion key={`short-${index}`} qaPair={pair} />)}
                    </div>
                </StudyGuideSection>
            )}

            {educationalContent.longAnswerQuestions?.length > 0 && (
                <StudyGuideSection title="Long Answer Questions" icon={<ChatBubbleLeftRightIcon className="w-6 h-6" />}>
                    <div className="space-y-3">
                        {educationalContent.longAnswerQuestions.map((pair, index) => <QuestionAccordion key={`long-${index}`} qaPair={pair} />)}
                    </div>
                </StudyGuideSection>
            )}

            {educationalContent.multipleChoiceQuestions?.length > 0 && (
                <StudyGuideSection title="Multiple Choice Questions" icon={<PuzzlePieceIcon className="w-6 h-6" />}>
                     <div className="space-y-3">
                        {educationalContent.multipleChoiceQuestions.map((mcq, index) => <MCQItem key={`mcq-${index}`} mcq={mcq} />)}
                    </div>
                    <button onClick={startQuiz} className="mt-6 w-full bg-green-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-green-700 transition-colors duration-300">Start Timed Quiz</button>
                </StudyGuideSection>
            )}
        </div>
      );
    }
    return null;
  }

  const hasInput = (inputMethod === 'image' && imageUrl) || (inputMethod === 'text' && textInput);

  return (
    <>
    <div className="min-h-screen bg-gray-900 text-gray-100 flex flex-col items-center p-4 sm:p-6 lg:p-8">
      <div className="w-full max-w-4xl mx-auto">
        <header className="text-center mb-6">
            <div className="flex justify-center items-center gap-4"><h1 className="text-4xl sm:text-5xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-indigo-600">AI Study Buddy</h1></div>
            <p className="mt-2 text-lg text-gray-400">Your personal AI-powered tutor for homework and exam prep.</p>
        </header>

        <main className="bg-gray-800 rounded-2xl shadow-2xl p-6">
          {!hasInput ? renderInitialView() : (
            <div className="flex flex-col lg:flex-row gap-6">
              <div className="lg:w-1/2 flex-shrink-0">
                <div className="relative group">
                  {imageUrl && inputMethod === 'image' ? <img src={imageUrl} alt="Uploaded page" className="w-full h-auto object-contain rounded-lg shadow-lg max-h-[60vh]" /> : <div className="bg-gray-900 p-4 rounded-lg max-h-[60vh] overflow-y-auto"><p className="text-gray-300 whitespace-pre-wrap">{textInput}</p></div> }
                  <button onClick={handleReset} className="absolute top-2 right-2 p-2 bg-black bg-opacity-50 rounded-full text-white hover:bg-opacity-75 transition-all opacity-0 group-hover:opacity-100 focus:opacity-100"><XCircleIcon className="w-6 h-6" /></button>
                </div>

                <div className="mt-4">
                    <label className="block text-sm font-medium text-gray-300 mb-2">Select Study Mode</label>
                    <div className="grid grid-cols-2 gap-2">
                        {studyModes.map((mode) => (
                            <button key={mode.id} onClick={() => setStudyMode(mode.id)} className={`p-3 text-sm font-semibold rounded-md transition-colors duration-200 text-left ${studyMode === mode.id ? 'bg-indigo-600 text-white ring-2 ring-indigo-400' : 'bg-gray-700 hover:bg-gray-600'}`}>
                                <span className="block font-bold">{mode.name}</span>
                                <span className="block text-xs opacity-80">{mode.description}</span>
                            </button>
                        ))}
                    </div>
                </div>

                <div className="mt-4 flex flex-col sm:flex-row gap-2">
                    <button onClick={handleSubmit} disabled={loadingState === 'processing'} className="w-full bg-indigo-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-colors duration-300 disabled:bg-gray-500 disabled:cursor-not-allowed"><SparklesIcon className="w-6 h-6" />{loadingState === 'processing' ? 'Generating...' : 'Generate Study Guide'}</button>
                    {loadingState === 'success' && (<button onClick={handleExportPdf} disabled={isExportingPdf} className="w-full sm:w-auto bg-gray-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-gray-700 transition-colors duration-300 disabled:bg-gray-500 disabled:cursor-not-allowed"><DocumentArrowDownIcon className="w-6 h-6"/>{isExportingPdf ? 'Exporting...' : 'Export PDF'}</button>)}
                </div>
              </div>

              <div className="lg:w-1/2 flex flex-col">{renderContent()}</div>
            </div>
          )}
        </main>
      </div>
    </div>
    </>
  );
};

