import React, { useEffect, useRef, useId } from 'react';
import mermaid from 'mermaid';

interface MermaidDiagramProps {
  chart: string;
}

// Initialize Mermaid
mermaid.initialize({
  startOnLoad: false,
  theme: 'dark',
  securityLevel: 'loose',
  themeVariables: {
    background: '#374151', // bg-gray-700
    primaryColor: '#374151', // bg-gray-700
    primaryTextColor: '#F3F4F6', // text-gray-100
    lineColor: '#A78BFA', // violet-400
    textColor: '#D1D5DB', // text-gray-300
    fontSize: '16px'
  }
});

const MermaidDiagram: React.FC<MermaidDiagramProps> = ({ chart }) => {
  const ref = useRef<HTMLDivElement>(null);
  const id = useId().replace(/:/g, ''); // Create a unique, CSS-safe ID

  useEffect(() => {
    if (ref.current && chart) {
        // Clear previous render to avoid duplicates
        ref.current.innerHTML = '';
        try {
            mermaid.render(`mermaid-svg-${id}`, chart, (svgCode) => {
                if (ref.current) {
                    ref.current.innerHTML = svgCode;
                }
            });
        } catch (e) {
            console.error("Mermaid render error:", e);
            if (ref.current) {
                ref.current.innerHTML = `<pre class="text-red-400">Error rendering diagram.\n${chart}</pre>`;
            }
        }
    }
  }, [chart, id]);

  // Display the raw code in a preformatted block for accessibility and debugging,
  // while the useEffect hook renders the SVG.
  return (
    <div ref={ref} className="mermaid-container bg-gray-700 p-4 rounded-lg flex justify-center w-full overflow-auto">
        <div className="mermaid" style={{ display: 'none' }}>{chart}</div>
    </div>
    );
};

export default MermaidDiagram;

