import React, { useState, useCallback, useRef } from 'react';
import { EducationalContent, StudyMode, QuizResult, DeepDiveContent } from './types';
import { generateEducationalContentFromImage, generateEducationalContentFromText, generateDeepDiveContentFromText } from './services/geminiService';
import QuestionAccordion from './components/QuestionAccordion';
import MCQItem from './components/MCQItem';
import Flashcard from './components/Flashcard';
import QuizView from './components/QuizView';
import QuizResultsView from './components/QuizResultsView';
import TextToSpeechButton from './components/TextToSpeechButton';
import MermaidDiagram from './components/MermaidDiagram';
import { CameraIcon, SparklesIcon, XCircleIcon, DocumentArrowDownIcon, MicrophoneIcon, BookOpenIcon, MapIcon, BoltIcon, CalculatorIcon, RectangleStackIcon, PencilIcon, ChatBubbleLeftRightIcon, PuzzlePieceIcon, ChevronDownIcon, ArrowPathIcon, BrainIcon, BeakerIcon, GlobeAmericasIcon, ClockIcon as HistoryIcon, LightBulbIcon as ExampleIcon, DocumentTextIcon  } from './components/icons';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';


type LoadingState = 'idle' | 'processing' | 'success' | 'error';
type InputMethod = 'image' | 'text';

const studyModes: { id: StudyMode, name: string, description: string, icon: React.ReactNode }[] = [
    { id: 'Student', name: 'Student Mode', description: 'For classes 6-12 homework help with step-by-step explanations.', icon: <BookOpenIcon className="w-12 h-12 mx-auto mb-4 text-indigo-400"/> },
    { id: 'KnowledgeBuilder', name: 'Knowledge Builder Mode', description: 'Build a complete knowledge base. Snap photos of your books to extract and master every key concept.', icon: <BoltIcon className="w-12 h-12 mx-auto mb-4 text-indigo-400"/> },
    { id: 'DeepDive', name: 'Deep Dive Q&A', description: 'Ask any question and get a comprehensive answer with theory, diagrams, and more.', icon: <BrainIcon className="w-12 h-12 mx-auto mb-4 text-indigo-400"/> },
];

// SpeechRecognition setup
const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
let recognition: any;
if (SpeechRecognition) {
    recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.lang = 'en-US';
    recognition.interimResults = false;
}

const StudyGuideSection: React.FC<{ title: string; icon: React.ReactNode; children: React.ReactNode; defaultOpen?: boolean }> = ({ title, icon, children, defaultOpen = false }) => {
