const getModeInstructions = (mode: StudyMode): string => {
    switch (mode) {
        case 'Student':
            return `
            **Mode:** Solve Homework
            **Persona:** Act as a friendly and patient AI tutor. Your primary goal is to help students understand their homework, not just get the answers.
            **Instructions:**
            - **Extreme Simplicity:** Explain everything in the simplest way possible. Assume the student is seeing this topic for the first time. Use short sentences and basic vocabulary.
            - **Relatable Examples:** Use everyday, relatable examples that a young student can easily understand.
            - **Step-by-Step Answers:** For every question, provide a clear, step-by-step explanation. Break down the solution into small, manageable parts. Explain the 'why' behind each step. For example, instead of just saying 'combine like terms', say 'Now, we'll group the terms with 'x' together and the plain numbers together, so it's easier to manage.'
            - **Focus on Homework:** The entire output should be geared towards helping a student complete and understand their homework assignment based on the provided text or image.
            `;
        case 'KnowledgeBuilder':
            return `
            **Mode:** Knowledge Builder
            **Persona:** Act as an AI Knowledge Architect.
            **Instructions:**
            - Your goal is to deconstruct the provided material into the most comprehensive set of notes and questions possible.
            - Extract every key concept, definition, formula, and nuanced relationship from the text. Be exhaustive.
            - Generate challenging questions (MCQs, VSA, SA, LA) that test deep understanding and the ability to connect different concepts presented in the text.
            - The final output should be a dense, high-quality knowledge base for mastering the subject, suitable for someone preparing for a competitive exam.
            `;
        default:
            return '';
    }
};

const getBasePrompt = (modeInstructions: string): string => {
    return `You are an advanced educational AI. Your first and most important task is to carefully analyze the provided content.

        ${modeInstructions}

        **Study Guide Generation Rules:**
        **CRITICAL LANGUAGE INSTRUCTION:** First, identify the primary language of the source text. All generated content (summaries, questions, answers, etc.) **MUST** be in that same identified language.

        **QUESTION GENERATION GOAL:** Your primary goal is to be comprehensive. Generate a varied set of questions and flashcards that collectively cover at least 80% of the key concepts from the source text.

        **Core Tasks:**
        1. Summarize the main topic in a concise paragraph.
        2. Create a structured mind map outline using a nested bullet point hierarchy.
        3. Create 'Quick Revision Notes' with only the most critical key points.
        4. Generate comprehensive flashcards, multiple choice questions (MCQ), very short answer questions (VSA), short answer questions (SA), and long answer questions (LA).
        5. Provide clear, well-explained answers for all questions.
        6. If the text contains any mathematical or scientific formulas/problems, identify them and provide a detailed, step-by-step explanation in the 'formulaExplanations' section. If none, this must be an empty array.

        Provide the output in a structured JSON format according to the provided schema.`;
};

export async function generateEducationalContentFromImage(base64ImageData: string, mimeType: string, mode: StudyMode): Promise<EducationalContent> {
    const imagePart = {
        inlineData: {
            data: base64ImageData,
            mimeType: mimeType,
        },
    };

    const modeInstructions = getModeInstructions(mode);
    const textPart = {
        text: `
        ${getBasePrompt(modeInstructions)}

        **Image-Specific Analysis Rules:**
        - Analyze the provided image of a textbook page or notes to extract the text content.
        - If parts of the text are unclear, try to reconstruct them from context. Ignore irrelevant scribbles.
        - If the image is completely unreadable, provide a polite error message in the 'topicSummary' field and empty arrays for other fields.
        `,
    };

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: [imagePart, textPart] },
            config: {
                responseMimeType: "application/json",
                responseSchema: educationalContentSchema,
            },
        });

        const jsonText = response.text;
        if (!jsonText) { throw new Error("API returned an empty response."); }
        return JSON.parse(jsonText) as EducationalContent;

    } catch (error) {
        console.error("Error calling Gemini API:", error);
        if (error instanceof Error && (error.message.includes('429') || error.message.toLowerCase().includes('resource_exhausted'))) {
            throw new Error("You've exceeded the API quota. Please check your plan and billing details, or try again later.");
        }
        throw new Error("Failed to generate study guide. The API may be busy or the image could not be processed.");
    }
}

export async function generateEducationalContentFromText(text: string, mode: StudyMode): Promise<EducationalContent> {
    const modeInstructions = getModeInstructions(mode);
    const textPart = {
        text: `
        ${getBasePrompt(modeInstructions)}

        **Source Text:**
        ---
        ${text}
        ---
        `,
    };

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: { parts: [textPart] },
            config: {
                responseMimeType: "application/json",
                responseSchema: educationalContentSchema,
            },
        });

        const jsonText = response.text;
        if (!jsonText) { throw new Error("API returned an empty response."); }
        return JSON.parse(jsonText) as EducationalContent;

    } catch (error) {
        console.error("Error calling Gemini API:", error);
        if (error instanceof Error && (error.message.includes('429') || error.message.toLowerCase().includes('resource_exhausted'))) {
            throw new Error("You've exceeded the API quota. Please check your plan and billing details, or try again later.");
        }
        throw new Error("Failed to generate study guide from text. Please try again.");
    }
}

export async function generateDeepDiveContentFromText(question: string): Promise<DeepDiveContent> {
    const prompt = `
    You are a world-class expert and educator. For the given question, provide a comprehensive 'deep dive' explanation. Your goal is to give the user a complete and thorough understanding of the topic from multiple angles.

    **User Question:** "${question}"

    **CRITICAL Instructions:**
    1.  **Identify Language:** First, identify the primary language of the user's question. All generated content **MUST** be in that same language.
    2.  **Be Comprehensive:** Cover the topic's core theory, relevant formulas with explanations, descriptive diagrams (using Mermaid syntax), practical examples, its history and origin, and its current real-world applications.
    3.  **Handle Missing Information:** If a section (like 'formulas' or 'diagrams') is not applicable to the topic, you **MUST** provide an empty array for that field in the JSON output. Do not omit the field.
    4.  **Diagrams:** For the 'diagrams' section, you **MUST** generate valid Mermaid.js syntax. For example: 'graph TD; A[Start]-->B{Decision}; B-->C[End];'. This is not optional if a diagram is relevant.

    Structure your response in JSON according to the provided schema.
    `;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: deepDiveContentSchema,
            },
        });

        const jsonText = response.text;
        if (!jsonText) { throw new Error("API returned an empty response."); }
        return JSON.parse(jsonText) as DeepDiveContent;
    } catch (error) {
        console.error("Error calling Gemini API for Deep Dive:", error);
        if (error instanceof Error && (error.message.includes('429') || error.message.toLowerCase().includes('resource_exhausted'))) {
            throw new Error("You've exceeded the API quota. Please check your plan and billing details, or try again later.");
        }
        throw new Error("Failed to generate deep dive content. Please try again.");
    }
}


export async function generateSpeech(text: string): Promise<string> {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' },
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) { throw new Error("No audio data returned from the API."); }
        return base64Audio;
    } catch (error) {
        console.error("Error generating speech:", error);
        if (error instanceof Error && (error.message.includes('429') || error.message.toLowerCase().includes('resource_exhausted'))) {
            throw new Error("API rate limit exceeded for audio generation. Please try again in a few moments.");
        }
        throw new Error("Failed to generate speech. The API may be temporarily unavailable.");
    }
}

export async function translateText(text: string, targetLanguage: string): Promise<string> {
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Translate the following text to ${targetLanguage}. Do not add any extra commentary, introductory phrases, or explanations. Only provide the direct translation of the text itself.\n\nText: "${text}"`,
        });

        const translatedText = response.text;
        if (!translatedText) { throw new Error("API returned an empty response for translation."); }
        return translatedText.trim();
    } catch (error) {
        console.error(`Error translating text to ${targetLanguage}:`, error);
        throw new Error(`Failed to translate text. Please try again.`);
    }
}

