  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) { processFile(file); }
  };

  const processFile = (file: File) => {
    setImageFile(file);
    const reader = new FileReader();
    reader.onload = (e) => {
      setImageUrl(e.target?.result as string);
      resetContentState();
    };
    reader.readAsDataURL(file);
  };

  const handleDrop = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.classList.remove('border-indigo-500');
    const file = event.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) { processFile(file); }
  };

  const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => event.preventDefault();
  const handleDragEnter = (event: React.DragEvent<HTMLDivElement>) => { event.preventDefault(); event.currentTarget.classList.add('border-indigo-500'); };
  const handleDragLeave = (event: React.DragEvent<HTMLDivElement>) => { event.preventDefault(); event.currentTarget.classList.remove('border-indigo-500'); };

  const handleSubmit = useCallback(async () => {
    if (!studyMode || ((inputMethod === 'image' && !imageUrl) || (inputMethod === 'text' && !textInput.trim()))) return;

    setLoadingState('processing');
    setErrorMessage(null);
    setEducationalContent(null);
    setIsQuizActive(false);
    setQuizResult(null);

    try {
      let result: EducationalContent;
      if (inputMethod === 'image' && imageUrl) {
        const base64Data = imageUrl.split(',')[1];
        result = await generateEducationalContentFromImage(base64Data, imageFile?.type || 'image/jpeg', studyMode);
      } else if (inputMethod === 'text' && textInput.trim()) {
        result = await generateEducationalContentFromText(textInput, studyMode);
      } else {
        throw new Error("Invalid input for generation.");
      }
      setEducationalContent(result);
      setLoadingState('success');
    } catch (error) {
      console.error(error);
      setErrorMessage(error instanceof Error ? error.message : 'An unknown error occurred.');
      setLoadingState('error');
    }
  }, [imageUrl, imageFile, studyMode, textInput, inputMethod]);

  const handleDeepDiveSubmit = async () => {
    if (!deepDiveQuestion.trim()) return;
    setLoadingState('processing');
    setErrorMessage(null);
    setDeepDiveContent(null);
    try {
        const result = await generateDeepDiveContentFromText(deepDiveQuestion);
        setDeepDiveContent(result);
        setLoadingState('success');
    } catch(error) {
        console.error(error);
        setErrorMessage(error instanceof Error ? error.message : 'An unknown error occurred.');
        setLoadingState('error');
    }
  };

  const resetContentState = () => {
    setEducationalContent(null);
    setDeepDiveContent(null);
    setLoadingState('idle');
    setErrorMessage(null);
    setIsQuizActive(false);
    setQuizResult(null);
  };

  const handleReset = () => {
    // Reset study guide inputs
    setImageFile(null);
    setImageUrl(null);
    setTextInput('');
    if(fileInputRef.current) { fileInputRef.current.value = ""; }
    // Reset deep dive inputs
    setDeepDiveQuestion('');
    // Reset shared content state
    resetContentState();
  };

  const handleModeChange = () => {
    handleReset();
    setStudyMode(null);
  }

  const handleVoiceInput = () => {
    if (!recognition || isListening) return;

    recognition.start();
    setIsListening(true);

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setTextInput(transcript);
    };
    recognition.onerror = (event: any) => { console.error('Speech recognition error:', event.error); setIsListening(false); };
    recognition.onend = () => { setIsListening(false); };
  };

  const handleQuizComplete = (answers: (string | null)[]) => {
    if (!educationalContent) return;
    const score = answers.reduce((acc, answer, index) => {
      if (answer === educationalContent.multipleChoiceQuestions[index].correctAnswer) {
        return acc + 1;
      }
      return acc;
    }, 0);
    setQuizResult({ score, answers });
    setIsQuizActive(false);
  };

  const startQuiz = () => {
    setQuizResult(null);
    setIsQuizActive(true);
  };

  const handleExportPdf = async () => {
    if (!contentRef.current) return;
    setIsExportingPdf(true);
    try {
        const canvas = await html2canvas(contentRef.current, { scale: 2, backgroundColor: '#1f2937' });
        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF({ orientation: 'p', unit: 'px', format: [canvas.width, canvas.height] });
        pdf.addImage(imgData, 'PNG', 0, 0, canvas.width, canvas.height);
        pdf.save('ai-study-buddy-guide.pdf');
    } catch (error) {
        console.error("Failed to export PDF:", error);
    } finally {
        setIsExportingPdf(false);
    }
  };

  const renderInitialView = () => (
    <div className="space-y-4">
      {inputMethod === 'image' ? (
        <>
            <div 
              className="w-full h-64 border-4 border-dashed border-gray-600 rounded-xl flex flex-col justify-center items-center text-center cursor-pointer hover:border-indigo-500 transition-colors duration-300"
              onClick={() => fileInputRef.current?.click()}
              onDrop={handleDrop} onDragOver={handleDragOver} onDragEnter={handleDragEnter} onDragLeave={handleDragLeave}
            >
              <CameraIcon className="w-16 h-16 text-gray-500 mb-4" />
              <h2 className="text-xl font-semibold text-gray-300">Upload an Image</h2>
              <p className="text-gray-400">Click to browse or drag & drop here</p>
              <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />
            </div>
            <p className="text-center text-sm text-gray-400">
                Or <button onClick={() => setInputMethod('text')} className="text-indigo-400 hover:underline">Use Voice or Text Input</button>
            </p>
        </>
      ) : (
        <>
            <div className="relative">
                <textarea
                    value={textInput}
                    onChange={(e) => {
                        setTextInput(e.target.value);
                        if(e.target.value) resetContentState();
                    }}
                    placeholder="Type or paste your text here, or use the microphone to speak..."
                    className="w-full h-64 p-4 bg-gray-900 border-2 border-gray-600 rounded-xl resize-none focus:border-indigo-500 focus:ring-0"
                />
                <button
                    onClick={handleVoiceInput}
                    disabled={!SpeechRecognition || isListening}
                    className={`absolute bottom-4 right-4 p-3 rounded-full transition-colors ${isListening ? 'bg-red-500 animate-pulse' : 'bg-indigo-600 hover:bg-indigo-700'} disabled:bg-gray-500 disabled:cursor-not-allowed`}
                    aria-label="Use voice input"
                >
                    <MicrophoneIcon className="w-6 h-6 text-white"/>
                </button>
            </div>
            <p className="text-center text-sm text-gray-400">
                Or <button onClick={() => setInputMethod('image')} className="text-indigo-400 hover:underline">Upload an Image</button>
            </p>
        </>
      )}
    </div>
  );

  const renderStudyGuideContent = () => {
    if (isQuizActive && educationalContent?.multipleChoiceQuestions) {
        return <QuizView mcqs={educationalContent.multipleChoiceQuestions} onQuizComplete={handleQuizComplete} />;
    }
    if (quizResult && educationalContent?.multipleChoiceQuestions) {
        return <QuizResultsView mcqs={educationalContent.multipleChoiceQuestions} result={quizResult} onRetake={startQuiz} onBackToStudyGuide={() => setQuizResult(null)} />;
    }
    if (loadingState === 'success' && educationalContent) {
      return (
        <div ref={contentRef} className="space-y-4 overflow-y-auto max-h-[80vh] p-1">
            <StudyGuideSection title="Topic Summary" icon={<BookOpenIcon className="w-6 h-6" />} defaultOpen>
                <p className="whitespace-pre-wrap text-gray-300">{educationalContent.topicSummary}</p>
                <TextToSpeechButton textToSpeak={educationalContent.topicSummary} />
            </StudyGuideSection>
            {educationalContent.mindMapOutline && <StudyGuideSection title="Mind Map Outline" icon={<MapIcon className="w-6 h-6" />}><pre className="whitespace-pre-wrap font-sans text-gray-300">{educationalContent.mindMapOutline}</pre><TextToSpeechButton textToSpeak={educationalContent.mindMapOutline} /></StudyGuideSection>}
            {educationalContent.revisionNotes && <StudyGuideSection title="Quick Revision Notes" icon={<BoltIcon className="w-6 h-6" />}><pre className="whitespace-pre-wrap font-sans text-gray-300">{educationalContent.revisionNotes}</pre><TextToSpeechButton textToSpeak={educationalContent.revisionNotes} /></StudyGuideSection>}
            {educationalContent.formulaExplanations?.length > 0 && <StudyGuideSection title="Formula & Problem Solvers" icon={<CalculatorIcon className="w-6 h-6" />}><div className="space-y-3">{educationalContent.formulaExplanations.map((item, index) => (<div key={index} className="bg-gray-700 p-4 rounded-lg"><p className="font-mono text-indigo-300 text-lg mb-2">{item.formula}</p><p className="text-gray-300 whitespace-pre-wrap">{item.explanation}</p><TextToSpeechButton textToSpeak={`Formula: ${item.formula}. Explanation: ${item.explanation}`} /></div>))}</div></StudyGuideSection>}
            {educationalContent.flashcards?.length > 0 && <StudyGuideSection title="Flashcards" icon={<RectangleStackIcon className="w-6 h-6" />}><div className="grid grid-cols-1 sm:grid-cols-2 gap-4">{educationalContent.flashcards.map((card, index) => <Flashcard key={`flashcard-${index}`} flashcard={card} />)}</div></StudyGuideSection>}

            {educationalContent.multipleChoiceQuestions?.length > 0 && <StudyGuideSection title="Multiple Choice Questions (MCQ)" icon={<PuzzlePieceIcon className="w-6 h-6" />}><div className="space-y-3">{educationalContent.multipleChoiceQuestions.map((mcq, index) => <MCQItem key={`mcq-${index}`} mcq={mcq} />)}</div><button onClick={startQuiz} className="mt-6 w-full bg-indigo-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-colors duration-300">Start Timed Quiz</button></StudyGuideSection>}
            {educationalContent.veryShortAnswerQuestions?.length > 0 && <StudyGuideSection title="Very Short Answer Questions (VSA)" icon={<PencilIcon className="w-6 h-6" />}><div className="space-y-3">{educationalContent.veryShortAnswerQuestions.map((pair, index) => <QuestionAccordion key={`vsa-${index}`} qaPair={pair} />)}</div></StudyGuideSection>}
            {educationalContent.shortAnswerQuestions?.length > 0 && <StudyGuideSection title="Short Answer Questions (SA)" icon={<ChatBubbleLeftRightIcon className="w-6 h-6" />}><div className="space-y-3">{educationalContent.shortAnswerQuestions.map((pair, index) => <QuestionAccordion key={`sa-${index}`} qaPair={pair} />)}</div></StudyGuideSection>}
            {educationalContent.longAnswerQuestions?.length > 0 && <StudyGuideSection title="Long Answer Questions (LA)" icon={<DocumentTextIcon className="w-6 h-6" />}><div className="space-y-3">{educationalContent.longAnswerQuestions.map((pair, index) => <QuestionAccordion key={`la-${index}`} qaPair={pair} />)}</div></StudyGuideSection>}
        </div>
      );
    }
    return null;
  }

  const renderDeepDiveContent = () => {
    if (loadingState === 'success' && deepDiveContent) {
        return (
            <div ref={contentRef} className="space-y-4 overflow-y-auto max-h-[80vh] p-1">
                <StudyGuideSection title="Core Theory" icon={<BeakerIcon className="w-6 h-6" />} defaultOpen><p className="whitespace-pre-wrap text-gray-300">{deepDiveContent.theory}</p><TextToSpeechButton textToSpeak={deepDiveContent.theory} /></StudyGuideSection>
                {deepDiveContent.formulas?.length > 0 && <StudyGuideSection title="Formulas" icon={<CalculatorIcon className="w-6 h-6" />}><div className="space-y-3">{deepDiveContent.formulas.map((item, index) => (<div key={index} className="bg-gray-800 p-4 rounded-lg"><p className="font-mono text-indigo-300 text-lg mb-2">{item.formula}</p><p className="text-gray-300 whitespace-pre-wrap">{item.explanation}</p><TextToSpeechButton textToSpeak={`Formula: ${item.formula}. Explanation: ${item.explanation}`} /></div>))}</div></StudyGuideSection>}
                {deepDiveContent.diagrams?.length > 0 && <StudyGuideSection title="Diagrams" icon={<MapIcon className="w-6 h-6" />}><div className="space-y-4">{deepDiveContent.diagrams.map((item, index) => (<div key={index}><p className="text-gray-300 mb-2">{item.description}</p><MermaidDiagram chart={item.mermaidCode} /></div>))}</div></StudyGuideSection>}
                {deepDiveContent.examples?.length > 0 && <StudyGuideSection title="Examples" icon={<ExampleIcon className="w-6 h-6" />}><div className="space-y-3">{deepDiveContent.examples.map((item, index) => (<div key={index} className="bg-gray-800 p-4 rounded-lg"><p className="font-bold text-gray-200 text-lg mb-2">{item.title}</p><p className="text-gray-300 whitespace-pre-wrap">{item.explanation}</p><TextToSpeechButton textToSpeak={`Example: ${item.title}. Explanation: ${item.explanation}`} /></div>))}</div></StudyGuideSection>}
                {deepDiveContent.history && <StudyGuideSection title="History & Origin" icon={<HistoryIcon className="w-6 h-6" />}><p className="whitespace-pre-wrap text-gray-300">{deepDiveContent.history}</p><TextToSpeechButton textToSpeak={deepDiveContent.history} /></StudyGuideSection>}
                {deepDiveContent.currentApplications && <StudyGuideSection title="Current Applications" icon={<GlobeAmericasIcon className="w-6 h-6" />}><p className="whitespace-pre-wrap text-gray-300">{deepDiveContent.currentApplications}</p><TextToSpeechButton textToSpeak={deepDiveContent.currentApplications} /></StudyGuideSection>}
            </div>
        );
    }
    return null;
  }

  const renderLoadingOrError = () => {
    if (loadingState === 'processing') {
      return <div className="flex flex-col items-center justify-center h-full text-center"><div className="w-12 h-12 border-4 border-t-indigo-500 border-gray-600 rounded-full animate-spin mb-4"></div><p className="text-lg font-semibold text-gray-300">Generating Content...</p><p className="text-gray-400">This might take a moment.</p></div>;
    }
    if (loadingState === 'error') {
      return <div className="flex items-center justify-center h-full text-center bg-red-900 bg-opacity-30 p-4 rounded-lg"><div><XCircleIcon className="w-12 h-12 text-red-400 mx-auto mb-2" /><p className="text-red-400 font-semibold">An error occurred</p><p className="text-red-300 text-sm">{errorMessage}</p></div></div>;
    }
    return null;
  }

  if (!studyMode) {
    return <ModeSelectionView onSelectMode={setStudyMode} />;
  }

  const currentModeDetails = studyModes.find(m => m.id === studyMode);

  const renderMainContent = () => {
    if (!((inputMethod === 'image' && imageUrl) || (inputMethod === 'text' && textInput))) {
      return renderInitialView();
    }

    // Split view for study guide generation
    return (
      <div className="flex flex-col lg:flex-row gap-6">
        <div className="lg:w-1/2 flex-shrink-0">
          <div className="relative group">
            {imageUrl && inputMethod === 'image' ? <img src={imageUrl} alt="Uploaded page" className="w-full h-auto object-contain rounded-lg shadow-lg max-h-[60vh]" /> : <div className="bg-gray-900 p-4 rounded-lg max-h-[60vh] overflow-y-auto"><p className="text-gray-300 whitespace-pre-wrap">{textInput}</p></div>}
            <button onClick={handleReset} className="absolute top-2 right-2 p-2 bg-black bg-opacity-50 rounded-full text-white hover:bg-opacity-75 transition-all opacity-0 group-hover:opacity-100 focus:opacity-100"><XCircleIcon className="w-6 h-6" /></button>
          </div>
          <div className="mt-4 flex flex-col sm:flex-row gap-2">
            <button onClick={handleSubmit} disabled={loadingState === 'processing'} className="w-full bg-indigo-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-colors duration-300 disabled:bg-gray-500 disabled:cursor-not-allowed"><SparklesIcon className="w-6 h-6" />{loadingState === 'processing' ? 'Generating...' : 'Generate'}</button>
            {loadingState === 'success' && (<button onClick={handleExportPdf} disabled={isExportingPdf} className="w-full sm:w-auto bg-gray-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-gray-700 transition-colors duration-300 disabled:bg-gray-500 disabled:cursor-not-allowed"><DocumentArrowDownIcon className="w-6 h-6"/>{isExportingPdf ? 'Exporting...' : 'Export PDF'}</button>)}
          </div>
        </div>
        <div className="lg:w-1/2 flex flex-col">
            {loadingState !== 'idle' ? renderLoadingOrError() : null}
            {renderStudyGuideContent()}
        </div>
      </div>
    );
  };


  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 flex flex-col items-center p-4 sm:p-6 lg:p-8">
      <div className="w-full max-w-4xl mx-auto">
        <header className="text-center mb-6">
            <div className="flex justify-center items-center gap-4">
                <h1 className="text-4xl sm:text-5xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-indigo-600">AI Study Buddy</h1>
                <button onClick={handleModeChange} className="bg-gray-700 text-gray-300 hover:bg-gray-600 hover:text-white px-3 py-1.5 rounded-lg text-sm flex items-center gap-2 transition-colors"><ArrowPathIcon className="w-4 h-4" />Change Mode</button>
            </div>
            <p className="mt-2 text-xl font-semibold text-indigo-300">{currentModeDetails?.name}</p>
        </header>

        {studyMode === 'DeepDive' ? (
             <main className="bg-gray-800 rounded-2xl shadow-2xl p-6">
                {!deepDiveContent && loadingState !== 'processing' && loadingState !== 'error' ? (
                     <div className="space-y-4">
                        <textarea
                            value={deepDiveQuestion}
                            onChange={(e) => setDeepDiveQuestion(e.target.value)}
                            placeholder="Ask any question to get a deep-dive explanation..."
                            className="w-full h-48 p-4 bg-gray-900 border-2 border-gray-600 rounded-xl resize-none focus:border-indigo-500 focus:ring-0"
                        />
                         {/* FIX: Although the error reported line 411, the type error described matches this button perfectly. The Typescript compiler correctly identified that `loadingState` can never be 'processing' in this render branch due to the outer conditional logic. Redundant `loadingState` checks from the button's `disabled` prop and text were removed. */}
                         <button onClick={handleDeepDiveSubmit} disabled={!deepDiveQuestion.trim()} className="w-full bg-indigo-600 text-white font-bold py-3 px-4 rounded-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-colors duration-300 disabled:bg-gray-500 disabled:cursor-not-allowed"><SparklesIcon className="w-6 h-6" />Generate Answer</button>
                    </div>
                ) : (
                    <>
                        {renderLoadingOrError()}
                        {renderDeepDiveContent()}
                        {(loadingState === 'success' || loadingState === 'error') && (
                            <div className="mt-4 text-center">
                                <button onClick={handleReset} className="text-indigo-400 hover:underline">Ask another question</button>
                            </div>
                        )}
                    </>
                )}
             </main>
        ) : (
            <main className="bg-gray-800 rounded-2xl shadow-2xl p-6">
                {renderMainContent()}
            </main>
        )}
      </div>
    </div>
  );
};

export default App;

