// Safely get the API key from environment variables. This function ensures the
// app doesn't crash in a browser environment where 'process' isn't defined.
// Netlify is responsible for making the API_KEY available.
const getApiKey = (): string => {
    // This code assumes that the deployment environment (e.g., Netlify with
    // snippet injection) will make the `API_KEY` available under `process.env`.
    const apiKey = (typeof process !== 'undefined' && process.env) ? process.env.API_KEY : undefined;

    if (!apiKey) {
        const errorMsg = "API_KEY is not configured. Please set the API_KEY environment variable in your Netlify deployment settings.";
        // Alert the user for immediate feedback during development/deployment.
        alert(`Configuration Error: ${errorMsg}`);
        throw new Error(errorMsg);
    }
    return apiKey;
};

const ai = new GoogleGenAI({ apiKey: getApiKey() });

