import React, { useState, useEffect } from 'react';
import { MapQuizTopic, MapQuizQuestion } from '../types';
import { mapQuizTopics } from '../data/mapData';
import IndiaMap from './IndiaMap';

type GameState = 'selecting' | 'playing' | 'finished';
type Feedback = { message: string; type: 'correct' | 'incorrect' } | null;

const MapPracticeView: React.FC = () => {
    const [gameState, setGameState] = useState<GameState>('selecting');
    const [selectedTopic, setSelectedTopic] = useState<MapQuizTopic | null>(null);
    const [questions, setQuestions] = useState<MapQuizQuestion[]>([]);
    const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
    const [score, setScore] = useState(0);
    const [feedback, setFeedback] = useState<Feedback>(null);
    const [clickedRegion, setClickedRegion] = useState<string | null>(null);

    const shuffleArray = (array: any[]) => {
        return [...array].sort(() => Math.random() - 0.5);
    };

    const handleTopicSelect = (topicId: string) => {
        const topic = mapQuizTopics.find(t => t.id === topicId);
        if (topic) {
            setSelectedTopic(topic);
            const shuffledQuestions = shuffleArray(topic.questions);
            setQuestions(shuffledQuestions);
            setCurrentQuestionIndex(0);
            setScore(0);
            setFeedback(null);
            setGameState('playing');
        }
    };

    const handleRegionClick = (regionId: string) => {
        if (gameState !== 'playing' || feedback) return;

        setClickedRegion(regionId);
        const currentQuestion = questions[currentQuestionIndex];

        if (regionId === currentQuestion.id) {
            setFeedback({ message: 'Correct!', type: 'correct' });
            setScore(prev => prev + 1);
            setTimeout(() => {
                if (currentQuestionIndex < questions.length - 1) {
                    setCurrentQuestionIndex(prev => prev + 1);
                    setFeedback(null);
                    setClickedRegion(null);
                } else {
                    setGameState('finished');
                }
            }, 1500);
        } else {
            const regionName = mapQuizTopics.flatMap(t => t.questions).find(q => q.id === regionId)?.name || 'that region';
            setFeedback({ message: `Not quite, that's ${regionName}. Try again!`, type: 'incorrect' });
             setTimeout(() => {
                setFeedback(null);
                setClickedRegion(null);
            }, 2000);
        }
    };

    const resetGame = () => {
        setGameState('selecting');
        setSelectedTopic(null);
        setQuestions([]);
    }

    const currentQuestion = questions[currentQuestionIndex];

    if (gameState === 'selecting') {
        return (
            <div>
                <h2 className="text-2xl font-bold text-center text-indigo-300 mb-6">Select a Map Quiz</h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {mapQuizTopics.map(topic => (
                        <button
                            key={topic.id}
                            onClick={() => handleTopicSelect(topic.id)}
                            className="bg-gray-700 p-6 rounded-lg text-lg font-semibold text-gray-200 hover:bg-indigo-600 hover:text-white transition-colors duration-300"
                        >
                            {topic.title}
                        </button>
                    ))}
                </div>
            </div>
        );
    }

    return (
        <div>
            <div className="text-center mb-4">
                {gameState === 'playing' && (
                    <>
                        <p className="text-gray-400">Question {currentQuestionIndex + 1} of {questions.length}</p>
                        <h2 className="text-2xl font-bold text-gray-100 my-2">{currentQuestion.prompt}</h2>
                        <p className="text-xl font-semibold text-indigo-300">Score: {score}</p>
                    </>
                )}
                {gameState === 'finished' && (
                     <>
                        <h2 className="text-3xl font-bold text-indigo-300 my-2">Quiz Complete!</h2>
                        <p className="text-2xl font-semibold text-gray-100">Final Score: {score} / {questions.length}</p>
                    </>
                )}
            </div>

            <div className="relative my-4">
                <IndiaMap
                    onRegionClick={handleRegionClick}
                    highlightCorrect={feedback?.type === 'correct' ? currentQuestion.id : null}
                    highlightIncorrect={feedback?.type === 'incorrect' ? clickedRegion : null}
                />
            </div>

            <div className="h-10 text-center flex items-center justify-center">
                {feedback && (
                    <p className={`text-xl font-bold ${feedback.type === 'correct' ? 'text-green-400' : 'text-red-400'}`}>
                        {feedback.message}
                    </p>
                )}
            </div>

            {gameState === 'finished' && (
                <div className="mt-4 flex justify-center gap-4">
                    <button
                        onClick={() => handleTopicSelect(selectedTopic!.id)}
                        className="px-6 py-2 bg-indigo-600 rounded-md hover:bg-indigo-500 font-bold"
                    >
                        Play Again
                    </button>
                     <button
                        onClick={resetGame}
                        className="px-4 py-2 bg-gray-600 rounded-md hover:bg-gray-500"
                    >
                        Choose Another Topic
                    </button>
                </div>
            )}
        </div>
    );
};

export default MapPracticeView;

