import { GoogleGenAI, Type, Modality } from "@google/genai";
import { EducationalContent, StudyMode, DeepDiveContent, QA_Pair } from '../types';

// Safely get the API key from environment variables. This function ensures the
// app doesn't crash in a browser environment where 'process' isn't defined.
// Netlify is responsible for making the API_KEY available.
const getApiKey = (): string => {
    // This code assumes that the deployment environment (e.g., Netlify with
    // snippet injection) will make the `API_KEY` available under `process.env`.
    const apiKey = (typeof process !== 'undefined' && process.env) ? process.env.API_KEY : undefined;

    if (!apiKey) {
        const errorMsg = "API_KEY is not configured. Please set the API_KEY environment variable in your Netlify deployment settings.";
        // Alert the user for immediate feedback during development/deployment.
        alert(`Configuration Error: ${errorMsg}`);
        throw new Error(errorMsg);
    }
    return apiKey;
};

const ai = new GoogleGenAI({ apiKey: getApiKey() });

const educationalContentSchema = {
    type: Type.OBJECT,
    properties: {
        topicSummary: {
            type: Type.STRING,
            description: "A summary of the main topic from the text."
        },
        mindMapOutline: {
            type: Type.STRING,
            description: "A hierarchical mind map outline of the topic using nested bullet points."
        },
        revisionNotes: {
            type: Type.STRING,
            description: "A concise, one-page summary with only the most critical key points, definitions, and formulas, formatted with bullet points for quick revision."
        },
        veryShortAnswerQuestions: {
            type: Type.ARRAY,
            description: "A list of very short answer questions (VSA) that can be answered in 1-2 sentences.",
            items: {
                type: Type.OBJECT,
                properties: {
                    question: { type: Type.STRING },
                    answer: { type: Type.STRING }
                },
                required: ["question", "answer"]
            }
