export async function generateExplanatoryQuestions(selectedText: string, fullContext: string): Promise<QA_Pair[]> {
    const prompt = `
    You are an expert teacher AI. Your goal is to explain a concept to a student in a simple, clear, and engaging way using a Socratic (question and answer) method.

    **Full Context of the Document:**
    ---
    ${fullContext}
    ---

    **User's Selected Text to Explain:**
    ---
    "${selectedText}"
    ---

    **Your Task:**
    Based on the **selected text**, generate a series of 3-5 simple questions and answers that break down and explain the concept.

    **CRITICAL Rules:**
    1.  **Focus on the selected text:** Your Q&A should primarily explain the user's selection. Use the full context only to understand the topic better, not to introduce unrelated information.
    2.  **Simple Language:** Ask questions a curious student would ask. Provide answers that are very easy to understand, as if you're explaining it for the first time. Use analogies if helpful.
    3.  **Start Broad, Get Specific:** The first question should be a general "What is..." or "Can you explain..." about the main idea in the selection. Subsequent questions should clarify details or define key terms from the selection.
    4.  **JSON Output:** Provide the output as a JSON array of objects, where each object has a "question" and "answer" key.
    `;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        explanations: explanatoryQuestionsSchema
                    }
                }
            },
        });

        const jsonText = response.text;
        if (!jsonText) { throw new Error("API returned an empty response."); }
        // The schema nests the result, so we need to parse and extract it.
        const parsed = JSON.parse(jsonText);
        return parsed.explanations as QA_Pair[];
    } catch (error) {
        console.error("Error calling Gemini API for Explanatory Questions:", error);
        if (error instanceof Error && (error.message.includes('429') || error.message.toLowerCase().includes('resource_exhausted'))) {
            throw new Error("API quota exceeded. Please try again later.");
        }
        throw new Error("Failed to generate explanation. Please try again.");
    }
}


export async function generateSpeech(text: string): Promise<string> {
    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: text }] }],
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: {
                        prebuiltVoiceConfig: { voiceName: 'Kore' },
                    },
                },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (!base64Audio) { throw new Error("No audio data returned from the API."); }
        return base64Audio;
    } catch (error) {
        console.error("Error generating speech:", error);
        if (error instanceof Error && (error.message.includes('429') || error.message.toLowerCase().includes('resource_exhausted'))) {
            throw new Error("API rate limit exceeded for audio generation. Please try again in a few moments.");
        }
        throw new Error("Failed to generate speech. The API may be temporarily unavailable.");
    }
}

export async function translateText(text: string, targetLanguage: string): Promise<string> {
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Translate the following text to ${targetLanguage}. Do not add any extra commentary, introductory phrases, or explanations. Only provide the direct translation of the text itself.\n\nText: "${text}"`,
