const App: React.FC = () => {
  const [studyMode, setStudyMode] = useState<StudyMode | null>(null);
  const [inputMethod, setInputMethod] = useState<InputMethod>('image');
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [textInput, setTextInput] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [loadingState, setLoadingState] = useState<LoadingState>('idle');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  // Content States
  const [educationalContent, setEducationalContent] = useState<EducationalContent | null>(null);
  const [quizGameContent, setQuizGameContent] = useState<QuizGameContent | null>(null);
  const [deepDiveContent, setDeepDiveContent] = useState<DeepDiveContent | null>(null);

  // Quiz State
  const [isQuizActive, setIsQuizActive] = useState(false);
  const [quizResult, setQuizResult] = useState<QuizResult | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);

  const resetContentState = () => {
    setEducationalContent(null);
    setQuizGameContent(null);
    setDeepDiveContent(null);
    setLoadingState('idle');
    setErrorMessage(null);
    setIsQuizActive(false);
    setQuizResult(null);
  };

  const handleReset = () => {
    setImageFile(null);
    setImageUrl(null);
    setTextInput('');
    if(fileInputRef.current) fileInputRef.current.value = "";
    resetContentState();
  };

  const handleSubmit = useCallback(async () => {
    if (!studyMode || ((inputMethod === 'image' && !imageUrl) || (inputMethod === 'text' && !textInput.trim()))) return;
    setLoadingState('processing');
    setErrorMessage(null);

    try {
      let result;
      if (inputMethod === 'image' && imageUrl) {
        result = await generateEducationalContentFromImage(imageUrl.split(',')[1], imageFile?.type || 'image/jpeg', studyMode);
      } else {
        result = await generateEducationalContentFromText(textInput, studyMode);
      }

      if (studyMode === 'QuizChallenge') {
        setQuizGameContent(result as QuizGameContent);
        setIsQuizActive(true);
      } else {
        setEducationalContent(result as EducationalContent);
      }
      setLoadingState('success');
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : 'Error occurred');
      setLoadingState('error');
    }
  }, [imageUrl, imageFile, studyMode, textInput, inputMethod]);

  const handleQuizComplete = (answers: (string | null)[]) => {
    const questions = quizGameContent ? quizGameContent.questions : (educationalContent?.multipleChoiceQuestions || []);
    const score = answers.reduce((acc, ans, i) => (ans === questions[i].correctAnswer ? acc + 1 : acc), 0);
    setQuizResult({ score, answers, totalQuestions: questions.length });
    setIsQuizActive(false);
  };

  const renderContent = () => {
    if (loadingState === 'processing') return <div className="p-20 text-center"><div className="animate-spin w-10 h-10 border-4 border-indigo-500 border-t-transparent rounded-full mx-auto mb-4"></div><p>Crafting your personal learning experience...</p></div>;

    if (isQuizActive && (quizGameContent || educationalContent)) {
        return <QuizGameView questions={quizGameContent ? quizGameContent.questions : educationalContent!.multipleChoiceQuestions} onComplete={handleQuizComplete} />;
    }

    if (quizResult && (quizGameContent || educationalContent)) {
        return <QuizGameResultView questions={quizGameContent ? quizGameContent.questions : educationalContent!.multipleChoiceQuestions} result={quizResult} onReset={handleReset} />;
    }

    if (educationalContent) {
        return (
            <div ref={contentRef} className="space-y-2">
                <StudyGuideSection title="Summary" icon={<BookOpenIcon className="w-6 h-6"/>} defaultOpen>
                    <p className="text-gray-300 leading-relaxed">{educationalContent.topicSummary}</p>
                </StudyGuideSection>
                {educationalContent.revisionNotes && <StudyGuideSection title="Revision Notes" icon={<BoltIcon className="w-6 h-6"/>}><pre className="whitespace-pre-wrap font-sans text-gray-300">{educationalContent.revisionNotes}</pre></StudyGuideSection>}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {educationalContent.flashcards.map((c, i) => <Flashcard key={i} flashcard={c} />)}
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {inputMethod === 'image' ? (
                <div onClick={() => fileInputRef.current?.click()} className="h-64 border-2 border-dashed border-gray-600 rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-indigo-500 transition-colors">
                    <CameraIcon className="w-12 h-12 text-gray-500 mb-2"/>
                    <p>Snap or Upload Image</p>
                    {imageUrl && <p className="text-xs text-indigo-400 mt-2">Image Selected!</p>}
                    <input type="file" ref={fileInputRef} onChange={(e) => {
                        const file = e.target.files?.[0];
                        if (file) {
                            setImageFile(file);
                            const r = new FileReader();
                            r.onload = (ev) => setImageUrl(ev.target?.result as string);
                            r.readAsDataURL(file);
                        }
                    }} accept="image/*" className="hidden" />
                </div>
            ) : (
                <textarea value={textInput} onChange={(e) => setTextInput(e.target.value)} placeholder="Type your topic here..." className="w-full h-64 bg-gray-900 border-2 border-gray-600 rounded-xl p-4 focus:border-indigo-500 outline-none" />
            )}
            <div className="flex gap-4">
                <button onClick={() => setInputMethod(inputMethod === 'image' ? 'text' : 'image')} className="flex-1 py-3 bg-gray-700 rounded-xl hover:bg-gray-600">Switch to {inputMethod === 'image' ? 'Text' : 'Image'}</button>
                <button onClick={handleSubmit} className="flex-1 py-3 bg-indigo-600 rounded-xl hover:bg-indigo-700 font-bold">Generate</button>
            </div>
        </div>
    );
  };

  if (!studyMode) return <ModeSelectionView onSelectMode={setStudyMode} />;

  return (
    <div className="min-h-screen bg-gray-900 p-4 sm:p-8">
        <div className="max-w-4xl mx-auto">
            <div className="flex justify-between items-center mb-8">
                <div>
                    <h1 className="text-3xl font-bold text-white">AI Study Buddy</h1>
                    <p className="text-indigo-400 font-medium">{studyModes.find(m => m.id === studyMode)?.name}</p>
                </div>
                <button onClick={() => setStudyMode(null)} className="p-2 bg-gray-800 rounded-lg hover:bg-gray-700"><ArrowPathIcon className="w-6 h-6"/></button>
            </div>
            <main className="bg-gray-800 rounded-3xl p-6 shadow-2xl">
                {renderContent()}
            </main>
        </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { MCQ } from '../types';
import { ClockIcon, SparklesIcon } from './icons';

interface QuizGameViewProps {
  questions: MCQ[];
  onComplete: (answers: (string | null)[]) => void;
}

const QuizGameView: React.FC<QuizGameViewProps> = ({ questions, onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<(string | null)[]>(Array(questions.length).fill(null));
  const [timeLeft, setTimeLeft] = useState(60 * 5); // 5 mins total

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLeft(t => {
        if (t <= 1) {
            clearInterval(timer);
            onComplete(answers);
            return 0;
        }
        return t - 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [answers, onComplete]);

  const currentQ = questions[currentIndex];
  const progress = ((currentIndex + 1) / questions.length) * 100;

  const handleSelect = (option: string) => {
    const newAnswers = [...answers];
    newAnswers[currentIndex] = option;
    setAnswers(newAnswers);

    // Auto-advance with a slight delay
    if (currentIndex < questions.length - 1) {
        setTimeout(() => setCurrentIndex(currentIndex + 1), 300);
    }
  };

  const formatTime = (s: number) => {
    const m = Math.floor(s / 60);
    const rs = s % 60;
    return `${m}:${rs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex justify-between items-center bg-gray-900/50 p-4 rounded-2xl border border-gray-700">
        <div className="flex items-center gap-3">
            <div className="bg-indigo-500/20 p-2 rounded-lg">
                <SparklesIcon className="w-6 h-6 text-indigo-400"/>
            </div>
            <div>
                <p className="text-xs text-gray-400 uppercase tracking-widest font-bold">Progress</p>
                <p className="text-sm font-bold text-white">Q {currentIndex + 1} / {questions.length}</p>
            </div>
        </div>
        <div className="flex items-center gap-2 bg-red-500/10 px-4 py-2 rounded-xl border border-red-500/20">
            <ClockIcon className="w-5 h-5 text-red-400"/>
            <span className="font-mono text-red-400 font-bold">{formatTime(timeLeft)}</span>
        </div>
      </div>

      <div className="w-full bg-gray-700 h-2 rounded-full overflow-hidden">
        <div className="bg-indigo-500 h-full transition-all duration-500" style={{ width: `${progress}%` }}></div>
      </div>

      <div className="bg-gray-900/30 p-8 rounded-3xl border border-gray-700/50 shadow-inner">
        <span className="inline-block px-3 py-1 bg-indigo-500/10 text-indigo-300 text-xs font-bold rounded-full mb-4 border border-indigo-500/20">
            {currentQ.category || 'General Concept'}
        </span>
        <h2 className="text-2xl font-bold text-gray-100 leading-tight mb-8">
            {currentQ.question}
        </h2>

        <div className="grid grid-cols-1 gap-4">
            {currentQ.options.map((opt, i) => (
                <button
                    key={i}
                    onClick={() => handleSelect(opt)}
                    className={`w-full text-left p-5 rounded-2xl border-2 transition-all duration-200 flex items-center gap-4 group ${
                        answers[currentIndex] === opt 
                        ? 'bg-indigo-600 border-indigo-400 text-white translate-x-1 shadow-lg shadow-indigo-500/20' 
                        : 'bg-gray-800 border-gray-700 hover:border-gray-500 hover:bg-gray-700'
                    }`}
                >
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold text-lg ${
                        answers[currentIndex] === opt ? 'bg-indigo-400 text-indigo-900' : 'bg-gray-700 text-gray-400 group-hover:bg-gray-600'
                    }`}>
                        {String.fromCharCode(65 + i)}
                    </div>
                    <span className="flex-1 font-medium">{opt}</span>
                </button>
            ))}
        </div>
      </div>

      <div className="flex justify-between items-center pt-4">
        <button 
            disabled={currentIndex === 0}
            onClick={() => setCurrentIndex(currentIndex - 1)}
            className="px-6 py-3 rounded-xl bg-gray-800 text-gray-400 hover:bg-gray-700 disabled:opacity-30 font-bold transition-all"
        >
            Previous
        </button>
        {currentIndex === questions.length - 1 ? (
            <button 
                onClick={() => onComplete(answers)}
                className="px-10 py-3 rounded-xl bg-green-600 text-white font-bold hover:bg-green-500 shadow-xl shadow-green-500/20 transition-all scale-105"
            >
                Submit Quiz
            </button>
        ) : (
            <button 
                onClick={() => setCurrentIndex(currentIndex + 1)}
                className="px-10 py-3 rounded-xl bg-indigo-600 text-white font-bold hover:bg-indigo-500 transition-all"
            >
                Next Q
            </button>
        )}
      </div>
    </div>
  );
};

