import React from 'react';
import { MCQ, QuizResult } from '../types';
import { CheckCircleIcon, XCircleIcon, SparklesIcon, ArrowPathIcon } from './icons';

interface QuizGameResultViewProps {
  questions: MCQ[];
  result: QuizResult;
  onReset: () => void;
}

const QuizGameResultView: React.FC<QuizGameResultViewProps> = ({ questions, result, onReset }) => {
  const percentage = Math.round((result.score / result.totalQuestions) * 100);

  const getRank = () => {
    if (percentage === 100) return { title: 'Master', color: 'text-yellow-400', bg: 'bg-yellow-400/10' };
    if (percentage >= 80) return { title: 'Scholar', color: 'text-green-400', bg: 'bg-green-400/10' };
    if (percentage >= 60) return { title: 'Apprentice', color: 'text-indigo-400', bg: 'bg-indigo-400/10' };
    return { title: 'Novice', color: 'text-gray-400', bg: 'bg-gray-400/10' };
  };

  const rank = getRank();

  // Concept Mastery Logic
  const categories = Array.from(new Set(questions.map(q => q.category || 'General')));
  const masteryData = categories.map(cat => {
    const catQs = questions.filter(q => (q.category || 'General') === cat);
    const correctCount = catQs.reduce((acc, q, i) => {
        const qIdx = questions.indexOf(q);
        return result.answers[qIdx] === q.correctAnswer ? acc + 1 : acc;
    }, 0);
    return {
        name: cat,
        percentage: Math.round((correctCount / catQs.length) * 100),
        count: catQs.length,
        correct: correctCount
    };
  });

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
      <div className="text-center bg-gray-900/40 p-10 rounded-[3rem] border border-gray-700 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-indigo-500 to-transparent"></div>

        <div className={`inline-block px-4 py-1 rounded-full text-xs font-black uppercase tracking-widest mb-4 ${rank.bg} ${rank.color}`}>
            Rank: {rank.title}
        </div>

        <h2 className="text-6xl font-black text-white mb-2">{percentage}%</h2>
        <p className="text-gray-400 font-medium">You solved {result.score} out of {result.totalQuestions} challenges correctly</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-gray-800/50 p-6 rounded-3xl border border-gray-700">
            <div className="flex items-center gap-3 mb-6">
                <SparklesIcon className="w-6 h-6 text-indigo-400"/>
                <h3 className="text-lg font-bold text-gray-100">Concept Mastery</h3>
            </div>
            <div className="space-y-4">
                {masteryData.map((m, i) => (
                    <div key={i} className="space-y-2">
                        <div className="flex justify-between text-sm">
                            <span className="text-gray-300 font-medium">{m.name}</span>
                            <span className={m.percentage < 60 ? 'text-red-400 font-bold' : 'text-green-400 font-bold'}>
                                {m.percentage}%
                            </span>
                        </div>
                        <div className="w-full bg-gray-900 h-2 rounded-full overflow-hidden">
                            <div 
                                className={`h-full transition-all duration-1000 ${m.percentage < 60 ? 'bg-red-500' : 'bg-green-500'}`} 
                                style={{ width: `${m.percentage}%` }}
                            ></div>
                        </div>
                        {m.percentage < 60 && <p className="text-[10px] text-red-400 uppercase font-black tracking-tighter">Needs a little closer study</p>}
                    </div>
                ))}
            </div>
        </div>

        <div className="bg-gray-800/50 p-6 rounded-3xl border border-gray-700 flex flex-col items-center justify-center text-center">
            <p className="text-gray-400 mb-6 italic">"Knowledge is power. Review your mistakes to grow your mastery."</p>
            <button 
                onClick={onReset}
                className="flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white font-black rounded-2xl hover:bg-indigo-500 transition-all shadow-xl shadow-indigo-600/20 active:scale-95"
            >
                <ArrowPathIcon className="w-6 h-6"/>
                Practice More
            </button>
        </div>
      </div>

      <div className="bg-gray-900/20 rounded-3xl p-6 border border-gray-700/50">
        <h3 className="text-xl font-bold text-gray-200 mb-6 px-2">Detailed Review</h3>
        <div className="space-y-4 max-h-[40vh] overflow-y-auto pr-2 custom-scrollbar">
            {questions.map((q, i) => {
                const isCorrect = result.answers[i] === q.correctAnswer;
                return (
                    <div key={i} className={`p-5 rounded-2xl border-l-4 ${isCorrect ? 'bg-green-500/5 border-green-500/50' : 'bg-red-500/5 border-red-500/50'}`}>
                        <div className="flex justify-between items-start mb-2 gap-4">
                            <p className="text-sm font-bold text-gray-200">{i + 1}. {q.question}</p>
                            {isCorrect ? <CheckCircleIcon className="w-6 h-6 text-green-500 shrink-0"/> : <XCircleIcon className="w-6 h-6 text-red-500 shrink-0"/>}
                        </div>
                        <div className="mt-3 grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs">
                            <div className="bg-gray-800/80 p-3 rounded-xl border border-gray-700">
                                <span className="text-gray-500 font-bold block mb-1 uppercase tracking-widest text-[10px]">Your Answer</span>
                                <span className={isCorrect ? 'text-green-400' : 'text-red-400'}>{result.answers[i] || 'Skipped'}</span>
                            </div>
                            {!isCorrect && (
                                <div className="bg-green-500/10 p-3 rounded-xl border border-green-500/20">
                                    <span className="text-green-600 font-bold block mb-1 uppercase tracking-widest text-[10px]">Correct Concept</span>
                                    <span className="text-green-300">{q.correctAnswer}</span>
                                </div>
                            )}
                        </div>
                    </div>
                );
            })}
        </div>
      </div>
    </div>
  );
};

