                        <div className="space-y-2">{educationalContent.shortAnswerQuestions.map((qa, i) => <QuestionAccordion key={i} qaPair={qa} />)}</div>
                    </StudyGuideSection>
                )}

                {educationalContent.longAnswerQuestions?.length > 0 && (
