  useEffect(() => {
    let unmounted = false; // Add a flag to handle unmounting

    const renderChart = async () => {
      if (!chartRef.current || unmounted) {
        return;
      }
      try {
        const { default: mermaid } = await import('mermaid');
        mermaid.initialize(mermaidConfig);
        const { svg } = await mermaid.render('mermaid-diagram', diagramCode);

        if (chartRef.current && !unmounted) { // Check if still mounted before setting innerHTML
          chartRef.current.innerHTML = svg;
        }
      } catch (error) {
        if (!unmounted) {
          console.error("Mermaid diagram rendering error:", error);
          const errorMessage =
            error instanceof Error ? error.message : 'Unknown error';
          chartRef.current.innerHTML = `
            <div style="color: red; padding: 10px; border: 1px solid red; border-radius: 4px;">
              <p>Error rendering Mermaid diagram:</p>
              <pre style="white-space: pre-wrap; word-break: break-word;">${errorMessage}</pre>
            </div>
          `;
        }
      }
    };
    renderChart();

    return () => {
      unmounted = true; // Set the flag to true when unmounting
    };
  }, [diagramCode, mermaidConfig]);
```

