                )}

                {educationalContent.multipleChoiceQuestions?.length > 0 && (
                    <StudyGuideSection title="Multiple Choice Questions" icon={<PuzzlePieceIcon className="w-6 h-6"/>}>
                        <div className="space-y-4">
                            {educationalContent.multipleChoiceQuestions.map((mcq, i) => <MCQItem key={i} mcq={mcq} />)}
                        </div>
                        <div className="mt-6 text-center">
                            <button
                                onClick={() => setIsQuizActive(true)}
                                className="px-8 py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-500 transition-all shadow-lg shadow-indigo-600/20"
                            >
                                Start Timed Quiz
                            </button>
                        </div>
                    </StudyGuideSection>
                )}
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {inputMethod === 'image' ? (
                <div onClick={() => fileInputRef.current?.click()} className="h-64 border-2 border-dashed border-gray-600 rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-indigo-500 transition-colors">
                    <CameraIcon className="w-12 h-12 text-gray-500 mb-2"/>
                    <p>Snap or Upload Image</p>
                    {imageUrl && <p className="text-xs text-indigo-400 mt-2">Image Selected!</p>}
                    <input type="file" ref={fileInputRef} onChange={(e) => {
                        const file = e.target.files?.[0];
                        if (file) {
                            setImageFile(file);
                            const r = new FileReader();
                            r.onload = (ev) => setImageUrl(ev.target?.result as string);
                            r.readAsDataURL(file);
                        }
                    }} accept="image/*" className="hidden" />
                </div>
            ) : (
                <textarea 
                    value={textInput} 
                    onChange={(e) => setTextInput(e.target.value)} 
                    placeholder={studyMode === 'DeepDive' ? "Ask a question for a deep dive..." : "Type your topic here..."}
                    className="w-full h-64 bg-gray-900 border-2 border-gray-600 rounded-xl p-4 focus:border-indigo-500 outline-none" 
                />
            )}
            <div className="flex gap-4">
                {studyMode !== 'DeepDive' && (
                    <button onClick={() => setInputMethod(inputMethod === 'image' ? 'text' : 'image')} className="flex-1 py-3 bg-gray-700 rounded-xl hover:bg-gray-600">Switch to {inputMethod === 'image' ? 'Text' : 'Image'}</button>
                )}
                <button 
                    onClick={handleSubmit} 
                    disabled={loadingState === 'processing' || (inputMethod === 'image' && !imageUrl) || (inputMethod === 'text' && !textInput.trim())}
                    className="flex-1 py-3 bg-indigo-600 rounded-xl hover:bg-indigo-700 font-bold disabled:bg-gray-600 disabled:cursor-not-allowed transition-colors"
                >
                    {loadingState === 'processing' ? 'Generating...' : 'Generate'}
                </button>
            </div>
        </div>
    );
  };

  if (!studyMode) return <ModeSelectionView onSelectMode={handleModeSelect} />;

  return (
    <div className="min-h-screen bg-gray-900 p-4 sm:p-8">
        <div className="max-w-4xl mx-auto">
            <div className="flex justify-between items-center mb-8">
                <div>
                    <h1 className="text-3xl font-bold text-white">EduScan AI</h1>
                    <p className="text-indigo-400 font-medium">{studyModes.find(m => m.id === studyMode)?.name}</p>
                </div>
                <button onClick={() => setStudyMode(null)} className="p-2 bg-gray-800 rounded-lg hover:bg-gray-700"><ArrowPathIcon className="w-6 h-6"/></button>
            </div>
            <main className="bg-gray-800 rounded-3xl p-6 shadow-2xl">
                {errorMessage && <div className="bg-red-500/20 text-red-300 p-4 rounded-lg mb-4">{errorMessage}</div>}
                {renderContent()}
            </main>
        </div>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { EducationalContent, StudyMode, DeepDiveContent, QA_Pair, QuizGameContent } from '../types';

const getApiKey = (): string => {
    const apiKey = (typeof process !== 'undefined' && process.env) ? process.env.API_KEY : undefined;
    if (!apiKey) {
        const errorMsg = "API_KEY is not configured.";
        alert(`Configuration Error: ${errorMsg}`);
        throw new Error(errorMsg);
    }
    return apiKey;
};

const ai = new GoogleGenAI({ apiKey: getApiKey() });

const mcqSchema = {
    type: Type.OBJECT,
    properties: {
        question: { type: Type.STRING },
        options: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
            minItems: 4,
            maxItems: 4
        },
        correctAnswer: { type: Type.STRING },
        category: { type: Type.STRING, description: "The specific concept or sub-topic this question tests (e.g., 'Dates', 'Formula Application', 'Definitions')." }
    },
    required: ["question", "options", "correctAnswer", "category"]
};

const educationalContentSchema = {
    type: Type.OBJECT,
    properties: {
        topicSummary: { type: Type.STRING },
        mindMapOutline: { type: Type.STRING },
        revisionNotes: { type: Type.STRING },
        veryShortAnswerQuestions: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: { question: { type: Type.STRING }, answer: { type: Type.STRING } },
                required: ["question", "answer"]
            }
        },
        shortAnswerQuestions: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: { question: { type: Type.STRING }, answer: { type: Type.STRING } },
                required: ["question", "answer"]
            }
        },
        longAnswerQuestions: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: { question: { type: Type.STRING }, answer: { type: Type.STRING } },
                required: ["question", "answer"]
            }
        },
        multipleChoiceQuestions: {
            type: Type.ARRAY,
            items: mcqSchema
        },
        formulaExplanations: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: { formula: { type: Type.STRING }, explanation: { type: Type.STRING } },
                required: ["formula", "explanation"]
            }
        },
        flashcards: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: { question: { type: Type.STRING }, answer: { type: Type.STRING } },
                required: ["question", "answer"]
            }
        }
    },
    required: ["topicSummary", "mindMapOutline", "revisionNotes", "veryShortAnswerQuestions", "shortAnswerQuestions", "longAnswerQuestions", "multipleChoiceQuestions", "formulaExplanations", "flashcards"]
};

const quizGameSchema = {
    type: Type.OBJECT,
    properties: {
        topic: { type: Type.STRING },
        questions: {
            type: Type.ARRAY,
            items: mcqSchema,
            minItems: 10,
            maxItems: 15
        }
    },
    required: ["topic", "questions"]
};

const deepDiveSchema = {
    type: Type.OBJECT,
    properties: {
        topic: { type: Type.STRING },
        theory: { type: Type.STRING },
        formulas: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    formula: { type: Type.STRING },
                    explanation: { type: Type.STRING }
                },
                required: ["formula", "explanation"]
            }
        },
        diagrams: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    description: { type: Type.STRING },
                    mermaidCode: { type: Type.STRING }
                },
                required: ["description", "mermaidCode"]
            }
        },
        examples: {
            type: Type.ARRAY,
            items: {
                type: Type.OBJECT,
                properties: {
                    title: { type: Type.STRING },
                    explanation: { type: Type.STRING }
                },
                required: ["title", "explanation"]
            }
        },
        history: { type: Type.STRING },
        currentApplications: { type: Type.STRING }
    },
    required: ["topic", "theory", "formulas", "diagrams", "examples", "history", "currentApplications"]
};


const getModeInstructions = (mode: StudyMode): string => {
    switch (mode) {
        case 'Student':
            return `**Mode:** Solve Homework. Patient AI tutor. Simple examples. Step-by-step.`;
        case 'KnowledgeBuilder':
            return `**Mode:** Create Notes. AI Knowledge Architect. Comprehensive extraction. Dense quality.`;
        case 'QuizChallenge':
            return `**Mode:** Quiz Challenge. Gamified assessment. Generate 10-15 high-quality MCQs. Categorize each question by concept. Ensure full coverage of input text.`;
        default:
            return '';
    }
};

const getBasePrompt = (modeInstructions: string): string => {
    return `You are an educational AI. Identify source language and respond in it.
        ${modeInstructions}
        Provide structured JSON output matching the requested schema.`;
};

export async function generateEducationalContentFromImage(base64ImageData: string, mimeType: string, mode: StudyMode): Promise<EducationalContent | QuizGameContent> {
    const imagePart = { inlineData: { data: base64ImageData, mimeType: mimeType } };
    const modeInstructions = getModeInstructions(mode);
    const schema = mode === 'QuizChallenge' ? quizGameSchema : educationalContentSchema;

    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [imagePart, { text: getBasePrompt(modeInstructions) }] },
        config: { responseMimeType: "application/json", responseSchema: schema as any },
    });
    return JSON.parse(response.text);
}

export async function generateEducationalContentFromText(text: string, mode: StudyMode): Promise<EducationalContent | QuizGameContent> {
    const modeInstructions = getModeInstructions(mode);
    const schema = mode === 'QuizChallenge' ? quizGameSchema : educationalContentSchema;

    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [{ text: `${getBasePrompt(modeInstructions)}\n\nSource: ${text}` }] },
        config: { responseMimeType: "application/json", responseSchema: schema as any },
    });
    return JSON.parse(response.text);
}

export async function generateDeepDiveContentFromText(question: string): Promise<DeepDiveContent> {
    const prompt = `You are an expert educator AI. Provide a comprehensive, deep-dive explanation for the following question. Use clear theory, relevant formulas, Mermaid diagrams for visualization, concrete examples, historical context, and current applications.

    Question: "${question}"

    Structure your response in JSON format according to the provided schema. If a section is not applicable, provide an empty array or an empty string.`;

    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { 
            responseMimeType: "application/json",
            responseSchema: deepDiveSchema as any 
        },
    });
    return JSON.parse(response.text);
}


export async function generateSpeech(text: string): Promise<string> {
    const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text }] }],
        config: { responseModalities: [Modality.AUDIO], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } } },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || '';
}

export async function translateText(text: string, targetLanguage: string): Promise<string> {
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Translate to ${targetLanguage}: ${text}`,
    });
    return response.text.trim();
}

import React, { useState, useCallback, useRef } from 'react';
import { EducationalContent, StudyMode, QuizResult, DeepDiveContent, QuizGameContent, LoadingState } from './types';
import { generateEducationalContentFromImage, generateEducationalContentFromText, generateDeepDiveContentFromText } from './services/geminiService';
import QuestionAccordion from './components/QuestionAccordion';
import MCQItem from './components/MCQItem';
import Flashcard from './components/Flashcard';
import QuizGameView from './components/QuizGameView';
import QuizGameResultView from './components/QuizGameResultView';
import LoadingView from './components/LoadingView';
import MermaidDiagram from './components/MermaidDiagram';
import { CameraIcon, BookOpenIcon, BoltIcon, CalculatorIcon, RectangleStackIcon, PencilIcon, ChatBubbleLeftRightIcon, PuzzlePieceIcon, ChevronDownIcon, ArrowPathIcon, BrainIcon, BeakerIcon, GlobeAmericasIcon, PhotoIcon, TrophyIcon } from './components/icons';

type InputMethod = 'image' | 'text';

const studyModes: { id: StudyMode, name: string, description: string, icon: React.ReactNode }[] = [
    { id: 'Student', name: 'Solve Homework', description: 'For classes 6-12 homework help with step-by-step explanations.', icon: <BookOpenIcon className="w-12 h-12 mx-auto mb-4 text-indigo-400"/> },
