    { id: 'QuizChallenge', name: 'Quiz Challenge', description: 'Turn any page into a gamified quiz. Discover your mastery and fix your mistakes.', icon: <TrophyIcon className="w-12 h-12 mx-auto mb-4 text-indigo-400"/> },
    { id: 'DeepDive', name: 'Deep Dive Q&A', description: 'Ask any question and get a comprehensive answer with theory and diagrams.', icon: <BrainIcon className="w-12 h-12 mx-auto mb-4 text-indigo-400"/> },
