                    {mode.icon}
                    <h2 className="text-xl font-bold text-indigo-300 mb-2">{mode.name}</h2>
                    <p className="text-sm text-gray-400">{mode.description}</p>
                </div>
            ))}
        </div>
    </div>
);

const App: React.FC = () => {
  const [studyMode, setStudyMode] = useState<StudyMode | null>(null);
  const [inputMethod, setInputMethod] = useState<InputMethod>('image');
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [textInput, setTextInput] = useState('');
  const [loadingState, setLoadingState] = useState<LoadingState>({ status: 'idle', stage: '', progress: 0 });
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  // Content States
  const [educationalContent, setEducationalContent] = useState<EducationalContent | null>(null);
  const [quizGameContent, setQuizGameContent] = useState<QuizGameContent | null>(null);
  const [deepDiveContent, setDeepDiveContent] = useState<DeepDiveContent | null>(null);

  // Quiz State
  const [isQuizActive, setIsQuizActive] = useState(false);
  const [quizResult, setQuizResult] = useState<QuizResult | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const loadingTimerRef = useRef<NodeJS.Timeout[]>([]);

  const resetContentState = () => {
    setEducationalContent(null);
    setQuizGameContent(null);
    setDeepDiveContent(null);
    setLoadingState({ status: 'idle', stage: '', progress: 0 });
    setErrorMessage(null);
    setIsQuizActive(false);
    setQuizResult(null);
  };

  const handleReset = () => {
    setImageFile(null);
    setImageUrl(null);
    setTextInput('');
    if(fileInputRef.current) fileInputRef.current.value = "";
    resetContentState();
  };

  const handleModeSelect = (mode: StudyMode) => {
    handleReset();
    setStudyMode(mode);
    if (mode === 'DeepDive') {
      setInputMethod('text');
    } else {
      setInputMethod('image');
    }
  };

  const clearLoadingTimers = () => {
    loadingTimerRef.current.forEach(clearTimeout);
    loadingTimerRef.current = [];
  };

  const handleSubmit = useCallback(async () => {
    if (!studyMode || ((inputMethod === 'image' && !imageUrl) || (inputMethod === 'text' && !textInput.trim()))) return;

    clearLoadingTimers();
    resetContentState();
    setLoadingState({ status: 'processing', stage: 'Initializing...', progress: 0 });

    // Simulate progress
    const stages = [
        { name: 'Analyzing Content', duration: 2000, progress: 25 },
        { name: 'Generating Summary', duration: 2500, progress: 50 },
        { name: 'Building Questions', duration: 3000, progress: 75 },
        { name: 'Finalizing', duration: 1500, progress: 95 }
    ];

    let cumulativeDelay = 0;
    stages.forEach(stage => {
        const timer = setTimeout(() => {
            setLoadingState(prev => ({ ...prev, stage: stage.name, progress: stage.progress }));
        }, cumulativeDelay);
        loadingTimerRef.current.push(timer);
        cumulativeDelay += stage.duration;
    });

    try {
        let result: EducationalContent | QuizGameContent | DeepDiveContent;
        if (studyMode === 'DeepDive') {
            result = await generateDeepDiveContentFromText(textInput);
            setDeepDiveContent(result);
        } else {
            if (inputMethod === 'image' && imageUrl) {
                result = await generateEducationalContentFromImage(imageUrl.split(',')[1], imageFile?.type || 'image/jpeg', studyMode);
            } else {
                result = await generateEducationalContentFromText(textInput, studyMode);
            }

            if (studyMode === 'QuizChallenge') {
                setQuizGameContent(result as QuizGameContent);
                setIsQuizActive(true);
            } else {
                setEducationalContent(result as EducationalContent);
            }
        }

        clearLoadingTimers();
        setLoadingState({ status: 'processing', stage: 'Complete!', progress: 100 });
        const finalTimer = setTimeout(() => {
            setLoadingState({ status: 'success', stage: '', progress: 0 });
        }, 500);
        loadingTimerRef.current.push(finalTimer);

    } catch (error) {
        clearLoadingTimers();
        const message = error instanceof Error ? error.message : 'An unknown error occurred';
        setErrorMessage(`Failed to generate content: ${message}. Please try again.`);
        setLoadingState({ status: 'error', stage: 'Error', progress: 0 });
    }
  }, [imageUrl, imageFile, studyMode, textInput, inputMethod]);

  const handleQuizComplete = (answers: (string | null)[]) => {
    const questions = quizGameContent ? quizGameContent.questions : (educationalContent?.multipleChoiceQuestions || []);
    const score = answers.reduce((acc, ans, i) => (ans === questions[i].correctAnswer ? acc + 1 : acc), 0);
    setQuizResult({ score, answers, totalQuestions: questions.length });
    setIsQuizActive(false);
  };

  const renderContent = () => {
    if (loadingState.status === 'processing') return <LoadingView progress={loadingState.progress} stage={loadingState.stage} />;

    if (isQuizActive && (quizGameContent || educationalContent?.multipleChoiceQuestions?.length)) {
        return <QuizGameView questions={quizGameContent ? quizGameContent.questions : educationalContent!.multipleChoiceQuestions} onComplete={handleQuizComplete} />;
    }

    if (quizResult && (quizGameContent || educationalContent?.multipleChoiceQuestions?.length)) {
        return <QuizGameResultView questions={quizGameContent ? quizGameContent.questions : educationalContent!.multipleChoiceQuestions} result={quizResult} onReset={handleReset} />;
    }

    if (deepDiveContent) {
        return (
            <div ref={contentRef} className="space-y-6 animate-in fade-in">
                <h2 className="text-3xl font-bold text-center text-indigo-300 mb-2">{deepDiveContent.topic}</h2>
                <StudyGuideSection title="Theory" icon={<BookOpenIcon className="w-6 h-6"/>} defaultOpen>
                    <p className="text-gray-300 whitespace-pre-wrap leading-relaxed">{deepDiveContent.theory}</p>
                </StudyGuideSection>
                {deepDiveContent.formulas?.length > 0 && <StudyGuideSection title="Key Formulas" icon={<CalculatorIcon className="w-6 h-6"/>}>{deepDiveContent.formulas.map((f, i) => <div key={i} className="bg-gray-800 p-4 rounded-lg mb-2"><p className="font-bold text-indigo-300 font-mono mb-2">{f.formula}</p><p className="text-gray-300 whitespace-pre-wrap">{f.explanation}</p></div>)}</StudyGuideSection>}
                {deepDiveContent.diagrams?.length > 0 && <StudyGuideSection title="Diagrams" icon={<PhotoIcon className="w-6 h-6"/>}>{deepDiveContent.diagrams.map((d, i) => <div key={i} className="mb-4"><p className="text-gray-300 mb-2">{d.description}</p><MermaidDiagram chart={d.mermaidCode} /></div>)}</StudyGuideSection>}
                {deepDiveContent.examples?.length > 0 && <StudyGuideSection title="Examples" icon={<BeakerIcon className="w-6 h-6"/>}>{deepDiveContent.examples.map((ex, i) => <QuestionAccordion key={i} qaPair={{ question: ex.title, answer: ex.explanation }} />)}</StudyGuideSection>}
                {deepDiveContent.history && <StudyGuideSection title="History & Context" icon={<GlobeAmericasIcon className="w-6 h-6"/>}><p className="text-gray-300 whitespace-pre-wrap leading-relaxed">{deepDiveContent.history}</p></StudyGuideSection>}
                {deepDiveContent.currentApplications && <StudyGuideSection title="Current Applications" icon={<BoltIcon className="w-6 h-6"/>}><p className="text-gray-300 whitespace-pre-wrap leading-relaxed">{deepDiveContent.currentApplications}</p></StudyGuideSection>}
            </div>
        );
    }

    if (educationalContent) {
        return (
            <div ref={contentRef} className="space-y-2">
                <StudyGuideSection title="Summary" icon={<BookOpenIcon className="w-6 h-6"/>} defaultOpen><p className="text-gray-300 leading-relaxed">{educationalContent.topicSummary}</p></StudyGuideSection>
                {educationalContent.revisionNotes && <StudyGuideSection title="Revision Notes" icon={<BoltIcon className="w-6 h-6"/>}><pre className="whitespace-pre-wrap font-sans text-gray-300">{educationalContent.revisionNotes}</pre></StudyGuideSection>}
                {educationalContent.formulaExplanations?.length > 0 && <StudyGuideSection title="Formula Explanations" icon={<CalculatorIcon className="w-6 h-6"/>}>{educationalContent.formulaExplanations.map((item, i) => <div key={i} className="bg-gray-800 p-4 rounded-lg mb-2"><p className="font-bold text-indigo-300 font-mono mb-2">{item.formula}</p><p className="text-gray-300 whitespace-pre-wrap">{item.explanation}</p></div>)}</StudyGuideSection>}
                {educationalContent.flashcards?.length > 0 && <StudyGuideSection title="Flashcards" icon={<RectangleStackIcon className="w-6 h-6"/>}><div className="grid grid-cols-1 sm:grid-cols-2 gap-4">{educationalContent.flashcards.map((c, i) => <Flashcard key={i} flashcard={c} />)}</div></StudyGuideSection>}
                {educationalContent.veryShortAnswerQuestions?.length > 0 && <StudyGuideSection title="Very Short Answer Questions" icon={<PencilIcon className="w-6 h-6"/>}>{educationalContent.veryShortAnswerQuestions.map((qa, i) => <QuestionAccordion key={i} qaPair={qa} />)}</StudyGuideSection>}
                {educationalContent.shortAnswerQuestions?.length > 0 && <StudyGuideSection title="Short Answer Questions" icon={<PencilIcon className="w-6 h-6"/>}>{educationalContent.shortAnswerQuestions.map((qa, i) => <QuestionAccordion key={i} qaPair={qa} />)}</StudyGuideSection>}
                {educationalContent.longAnswerQuestions?.length > 0 && <StudyGuideSection title="Long Answer Questions" icon={<ChatBubbleLeftRightIcon className="w-6 h-6"/>}>{educationalContent.longAnswerQuestions.map((qa, i) => <QuestionAccordion key={i} qaPair={qa} />)}</StudyGuideSection>}
                {educationalContent.multipleChoiceQuestions?.length > 0 && <StudyGuideSection title="Multiple Choice Questions" icon={<PuzzlePieceIcon className="w-6 h-6"/>}><div className="space-y-4">{educationalContent.multipleChoiceQuestions.map((mcq, i) => <MCQItem key={i} mcq={mcq} />)}</div><div className="mt-6 text-center"><button onClick={() => setIsQuizActive(true)} className="px-8 py-3 bg-indigo-600 text-white font-bold rounded-xl hover:bg-indigo-500 transition-all shadow-lg shadow-indigo-600/20">Start Timed Quiz</button></div></StudyGuideSection>}
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {inputMethod === 'image' ? (
                <div onClick={() => fileInputRef.current?.click()} className="h-64 border-2 border-dashed border-gray-600 rounded-xl flex flex-col items-center justify-center cursor-pointer hover:border-indigo-500 transition-colors">
                    <CameraIcon className="w-12 h-12 text-gray-500 mb-2"/>
                    <p>Snap or Upload Image</p>
                    {imageUrl && <p className="text-xs text-indigo-400 mt-2">Image Selected!</p>}
                    <input type="file" ref={fileInputRef} onChange={(e) => { const file = e.target.files?.[0]; if (file) { setImageFile(file); const r = new FileReader(); r.onload = (ev) => setImageUrl(ev.target?.result as string); r.readAsDataURL(file); } }} accept="image/*" className="hidden" />
                </div>
            ) : (
                <textarea value={textInput} onChange={(e) => setTextInput(e.target.value)} placeholder={studyMode === 'DeepDive' ? "Ask a question for a deep dive..." : "Type your topic here..."} className="w-full h-64 bg-gray-900 border-2 border-gray-600 rounded-xl p-4 focus:border-indigo-500 outline-none" />
            )}
            <div className="flex gap-4">
                {studyMode !== 'DeepDive' && (<button onClick={() => setInputMethod(inputMethod === 'image' ? 'text' : 'image')} className="flex-1 py-3 bg-gray-700 rounded-xl hover:bg-gray-600">Switch to {inputMethod === 'image' ? 'Text' : 'Image'}</button>)}
                <button onClick={handleSubmit} disabled={loadingState.status === 'processing' || (inputMethod === 'image' && !imageUrl) || (inputMethod === 'text' && !textInput.trim())} className="flex-1 py-3 bg-indigo-600 rounded-xl hover:bg-indigo-700 font-bold disabled:bg-gray-600 disabled:cursor-not-allowed transition-colors">
                    {loadingState.status === 'processing' ? 'Generating...' : 'Generate'}
                </button>
            </div>
        </div>
    );
  };

  if (!studyMode) return <ModeSelectionView onSelectMode={handleModeSelect} />;

  return (
    <div className="min-h-screen bg-gray-900 p-4 sm:p-8">
        <div className="max-w-4xl mx-auto">
            <div className="flex justify-between items-center mb-8">
                <div>
                    <h1 className="text-3xl font-bold text-white">EduScan AI</h1>
                    <p className="text-indigo-400 font-medium">{studyModes.find(m => m.id === studyMode)?.name}</p>
                </div>
                <button onClick={() => { setStudyMode(null); handleReset(); }} className="p-2 bg-gray-800 rounded-lg hover:bg-gray-700"><ArrowPathIcon className="w-6 h-6"/></button>
            </div>
            <main className="bg-gray-800 rounded-3xl p-6 shadow-2xl">
                {errorMessage && <div className="bg-red-500/20 text-red-300 p-4 rounded-lg mb-4">{errorMessage}</div>}
                {renderContent()}
            </main>
        </div>
    </div>
  );
};

export default App;

export interface QA_Pair {
  question: string;
  answer: string;
}

export interface MCQ {
  question: string;
  options: string[];
  correctAnswer: string;
  category?: string; // Concept category for mastery tracking
}

export interface FormulaExplanation {
    formula: string;
    explanation: string;
}

export interface Flashcard {
  question: string;
  answer: string;
}

export interface EducationalContent {
  topicSummary: string;
  mindMapOutline: string;
  revisionNotes: string;
  veryShortAnswerQuestions: QA_Pair[];
  shortAnswerQuestions: QA_Pair[];
  longAnswerQuestions: QA_Pair[];
  multipleChoiceQuestions: MCQ[];
  formulaExplanations: FormulaExplanation[];
  flashcards: Flashcard[];
}

export type StudyMode = 'Student' | 'KnowledgeBuilder' | 'DeepDive' | 'QuizChallenge';

export interface QuizResult {
  score: number;
  answers: (string | null)[];
  totalQuestions: number;
}

// Types for the new Deep Dive Feature
export interface FormulaDetail {
    formula: string;
    explanation: string;
}

export interface DiagramDetail {
    description: string;
    mermaidCode: string; 
}

export interface ExampleDetail {
    title: string;
    explanation: string;
}

export interface DeepDiveContent {
  topic: string;
  theory: string;
  formulas: FormulaDetail[];
  diagrams: DiagramDetail[];
  examples: ExampleDetail[];
  history: string;
  currentApplications: string;
}

export interface QuizGameContent {
  topic: string;
  questions: MCQ[];
}

export interface LoadingState {
  status: 'idle' | 'processing' | 'success' | 'error';
  stage: string;
  progress: number;
}

import React, { useState, useEffect } from 'react';
import { CheckCircleIcon, LightBulbIcon } from './icons';

interface LoadingViewProps {
  progress: number;
  stage: string;
}

const tips = [
  "The 'Ebbinghaus Forgetting Curve' shows we forget information over time unless we review it. Use flashcards to combat this!",
  "Teaching a concept to someone else is a powerful way to solidify your own understanding. Try explaining a topic to a friend.",
  "The 'Pomodoro Technique' can boost focus: work for 25 minutes, then take a 5-minute break.",
  "Connecting new information to what you already know creates stronger neural pathways, making it easier to remember.",
  "A good night's sleep is crucial for memory consolidation. Your brain processes and stores information while you rest.",
  "The human brain has about 86 billion neurons, each connected to thousands of others.",
];

const LoadingView: React.FC<LoadingViewProps> = ({ progress, stage }) => {
  const [currentTip, setCurrentTip] = useState(tips[0]);

  useEffect(() => {
    const tipInterval = setInterval(() => {
      setCurrentTip(prevTip => {
        const currentIndex = tips.indexOf(prevTip);
        const nextIndex = (currentIndex + 1) % tips.length;
        return tips[nextIndex];
      });
    }, 4000); // Change tip every 4 seconds

    return () => clearInterval(tipInterval);
  }, []);

  const loadingStages = ['Analyzing Content', 'Generating Summary', 'Building Questions', 'Finalizing'];
  const currentStageIndex = loadingStages.indexOf(stage) >= 0 ? loadingStages.indexOf(stage) : (progress === 100 ? loadingStages.length : -1);

  return (
    <div className="p-8 text-center space-y-8 animate-in fade-in duration-500">
      <h2 className="text-2xl font-bold text-gray-200">EduScan AI is thinking...</h2>

      {/* Progress Bar */}
      <div className="w-full bg-gray-700 rounded-full h-4">
        <div 
          className="bg-gradient-to-r from-purple-500 to-indigo-500 h-4 rounded-full transition-all duration-500 ease-out" 
          style={{ width: `${progress}%` }}
        ></div>
      </div>
      <p className="font-mono text-indigo-300 text-lg">{stage}</p>

      {/* Stage List */}
      <div className="flex justify-between items-center text-xs text-gray-400 max-w-md mx-auto">
        {loadingStages.map((s, index) => (
          <div key={s} className="flex flex-col items-center gap-2">
            <div className={`w-8 h-8 rounded-full flex items-center justify-center border-2 transition-all duration-300 ${
                index < currentStageIndex ? 'bg-green-500/20 border-green-500' : 
                index === currentStageIndex ? 'border-indigo-500' : 
                'border-gray-600'
            }`}>
              {index < currentStageIndex ? (
                <CheckCircleIcon className="w-5 h-5 text-green-400"/>
              ) : index === currentStageIndex ? (
                <div className="w-4 h-4 rounded-full bg-indigo-500 animate-pulse"></div>
              ) : (
                <div className="w-2 h-2 rounded-full bg-gray-600"></div>
              )}
            </div>
            <span className={index <= currentStageIndex ? 'text-gray-200 font-semibold' : 'text-gray-500'}>{s}</span>
          </div>
        ))}
      </div>

      {/* Did you know? */}
      <div className="pt-6 border-t border-gray-700/50">
        <div className="bg-gray-900/30 p-4 rounded-2xl max-w-md mx-auto border border-gray-700">
          <div className="flex items-center gap-3 mb-2">
            <LightBulbIcon className="w-5 h-5 text-yellow-400"/>
            <h4 className="font-bold text-sm text-yellow-300">Did you know?</h4>
          </div>
          <p className="text-xs text-gray-400 transition-opacity duration-500">{currentTip}</p>
        </div>
      </div>
    </div>
  );
};

export default LoadingView;

